def _set_recurring_to_redis(table_name, user_id, data):
    """
    Set recurring records to Redis and mark dirty for flush.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        data: List of recurring records
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(data, cls=DecimalEncoder)
        )
        
        # Mark table as dirty for flush worker
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        app.logger.error(f"Error setting {table_name} to Redis: {e}")

def _update_recurring_in_redis(table_name, user_id, recurring_data):
    """
    Update or insert a single recurring record in Redis cache.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        recurring_data: Dict with recurring record data (must include 'id' for update or None for insert)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
        else:
            rows = []
        
        recurring_id = recurring_data.get('id')
        
        if recurring_id:
            # Update existing record
            found = False
            for i, row in enumerate(rows):
                if int(row.get('id')) == int(recurring_id):
                    # Preserve category_name if not provided in update
                    if 'category_name' not in recurring_data and 'category_name' in row:
                        recurring_data['category_name'] = row['category_name']
                    rows[i] = recurring_data
                    found = True
                    break
            
            if not found:
                # Record not in cache, add it
                rows.append(recurring_data)
        else:
            # New record - generate a temporary negative ID (will be replaced by MySQL on flush)
            temp_id = -int(time.time() * 1000000)  # Use negative timestamp to avoid collisions
            recurring_data['id'] = temp_id
            rows.append(recurring_data)
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        
    except Exception as e:
        app.logger.error(f"Error updating {table_name} in Redis: {e}")

def _delete_recurring_in_redis(table_name, user_id, recurring_id):
    """
    Delete a recurring record from Redis cache.
    
    Args:
        table_name: 'recurring_income', 'recurring_expense', or 'recurring_c_expense'
        user_id: User ID
        recurring_id: ID of the recurring record to delete
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            # Filter out the deleted record (compare as int to handle both int and str IDs)
            recurring_id_int = int(recurring_id)
            rows = [row for row in rows if int(row.get('id')) != recurring_id_int]
            
            # Save back to Redis
            _redis_client.setex(
                redis_key,
                PERSISTENT_CACHE_TTL,
                json.dumps(rows, cls=DecimalEncoder)
            )
        
        # Track pending deletion for flush worker (only for real MySQL IDs, not temp negative IDs)
        recurring_id_int = int(recurring_id)
        if recurring_id_int > 0:
            pending_key = f"pending_deletes:{table_name}:{user_id}"
            _redis_client.sadd(pending_key, str(recurring_id))
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
        else:
            pass
        
        # Mark as dirty
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        app.logger.error(f"Error deleting {table_name} in Redis: {e}")

def _delete_category_in_redis(table_name, user_id, category_id):
    """
    Delete a category record from Redis cache and all associated entries and buckets.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (or account_id for c_expense_categories)
        category_id: ID of the category to delete
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        category_id_int = int(category_id)
        
        # Determine table names for related entries and buckets
        # All tables now use user_id as the key
        if table_name == 'income_categories':
            entries_table = 'income_entries'
            buckets_table = 'recurring_income_buckets'
        elif table_name == 'expense_categories':
            entries_table = 'expense_entries'
            buckets_table = 'recurring_expense_buckets'
        elif table_name == 'c_expense_categories':
            entries_table = 'c_expense_entries'
            buckets_table = 'recurring_c_expense_buckets'
        else:
            entries_table = None
            buckets_table = None
        
        # user_id is now always the actual user_id
        pending_user_id = user_id
        
        # 1. Delete all entries for this category
        if entries_table:
            entries_key = f"{entries_table}:v1:{pending_user_id}"
            entries_cached = _redis_client.get(entries_key)
            if entries_cached:
                entries = json.loads(entries_cached)
                deleted_entry_ids = []
                filtered_entries = []
                
                for entry in entries:
                    if int(entry.get('category_id', 0)) == category_id_int:
                        # This entry belongs to the deleted category
                        entry_id = entry.get('id')
                        if entry_id and int(entry_id) > 0:
                            deleted_entry_ids.append(str(entry_id))
                    else:
                        filtered_entries.append(entry)
                
                # Save filtered entries back to Redis
                _redis_client.setex(
                    entries_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(filtered_entries, cls=DecimalEncoder)
                )
                
                # Track pending entry deletions
                if deleted_entry_ids:
                    pending_entries_key = f"pending_deletes:{entries_table}:{pending_user_id}"
                    _redis_client.sadd(pending_entries_key, *deleted_entry_ids)
                    _redis_client.expire(pending_entries_key, PERSISTENT_CACHE_TTL)
                    
                    # Mark entries table as dirty
                    dirty_key = f"dirty_tables:{pending_user_id}"
                    _redis_client.sadd(dirty_key, entries_table)
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        # 2. Delete all buckets for this category
        if buckets_table:
            buckets_key = f"{buckets_table}:v1:{pending_user_id if table_name != 'c_expense_categories' else user_id}"
            buckets_cached = _redis_client.get(buckets_key)
            if buckets_cached:
                buckets = json.loads(buckets_cached)
                deleted_bucket_ids = []
                filtered_buckets = []
                
                for bucket in buckets:
                    if int(bucket.get('category_id', 0)) == category_id_int:
                        # This bucket belongs to the deleted category
                        bucket_id = bucket.get('id')
                        if bucket_id and int(bucket_id) > 0:
                            deleted_bucket_ids.append(str(bucket_id))
                    else:
                        filtered_buckets.append(bucket)
                
                # Save filtered buckets back to Redis
                _redis_client.setex(
                    buckets_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(filtered_buckets, cls=DecimalEncoder)
                )
                
                # Track pending bucket deletions
                if deleted_bucket_ids:
                    pending_buckets_key = f"pending_deletes:{buckets_table}:{pending_user_id}"
                    _redis_client.sadd(pending_buckets_key, *deleted_bucket_ids)
                    _redis_client.expire(pending_buckets_key, PERSISTENT_CACHE_TTL)
                    
                    # Mark buckets table as dirty
                    dirty_key = f"dirty_tables:{pending_user_id}"
                    _redis_client.sadd(dirty_key, buckets_table)
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        # 3. Delete the category itself
        redis_key = f"{table_name}:v1:{user_id}"
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            original_count = len(rows)
            rows = [row for row in rows if int(row.get('id')) != category_id_int]
            deleted_count = original_count - len(rows)
            
            # Save back to Redis
            _redis_client.setex(
                redis_key,
                PERSISTENT_CACHE_TTL,
                json.dumps(rows, cls=DecimalEncoder)
            )
            
        
        # Track pending category deletion (only for real MySQL IDs, not temp negative IDs)
        if category_id_int > 0:
            pending_key = f"pending_deletes:{table_name}:{pending_user_id}"
            _redis_client.sadd(pending_key, str(category_id))
            _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
        else:
            pass
        
        # Mark category table as dirty
        dirty_key = f"dirty_tables:{pending_user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
    except Exception as e:
        app.logger.error(f"Error deleting category from {table_name} in Redis: {e}")

def _delete_buckets_in_redis(table_name, user_id, category_id):
    """
    Delete all bucket records for a category from Redis cache.
    
    Args:
        table_name: 'recurring_income_buckets', 'recurring_expense_buckets', or 'recurring_c_expense_buckets'
        user_id: User ID (or account_id for c_expense buckets)
        category_id: ID of the category whose buckets should be deleted
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            # Filter out all buckets for this category
            category_id_int = int(category_id)
            original_count = len(rows)
            rows = [row for row in rows if int(row.get('category_id')) != category_id_int]
            deleted_count = original_count - len(rows)
            
            if deleted_count > 0:
                # Save back to Redis
                _redis_client.setex(
                    redis_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(rows, cls=DecimalEncoder)
                )
                
                # Mark as dirty
                if table_name == 'recurring_c_expense_buckets':
                    # Get actual user_id for c_expense buckets
                    actual_user_id = current_user.id if current_user.is_authenticated else None
                    if not actual_user_id:
                        account_id = user_id
                        accounts = _get_credit_accounts_from_redis(current_user.id) if current_user.is_authenticated else None
                        if accounts:
                            account = next((a for a in accounts if a.get('id') == account_id), None)
                            if account:
                                actual_user_id = account.get('user_id')
                    dirty_user_id = actual_user_id if actual_user_id else user_id
                else:
                    dirty_user_id = user_id
                
                dirty_key = f"dirty_tables:{dirty_user_id}"
                _redis_client.sadd(dirty_key, table_name)
                _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                
        
    except Exception as e:
        app.logger.error(f"Error deleting buckets from {table_name} in Redis: {e}")


def _delete_future_buckets_in_redis(table_name, user_id, category_id, from_date=None):
    """
    Delete future bucket records for a category from Redis cache (from today onwards).
    
    Args:
        table_name: 'recurring_income_buckets', 'recurring_expense_buckets', or 'recurring_c_expense_buckets'
        user_id: User ID
        category_id: ID of the category whose future buckets should be deleted
        from_date: Date to start deleting from (defaults to today)
    """
    if not app.config.get('REDIS_OK'):
        return
    
    if from_date is None:
        from_date = datetime.today().date()
    elif isinstance(from_date, str):
        from_date = datetime.strptime(from_date, '%Y-%m-%d').date()
    
    from_date_str = from_date.isoformat()
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if cached:
            rows = json.loads(cached)
            category_id_int = int(category_id)
            original_count = len(rows)
            
            # Track deleted bucket IDs for pending_deletes
            deleted_bucket_ids = []
            kept_rows = []
            
            for row in rows:
                bucket_category_id = int(row.get('category_id'))
                bucket_date = row.get('bucket_date')
                if isinstance(bucket_date, str):
                    bucket_date_str = bucket_date
                else:
                    bucket_date_str = bucket_date.isoformat() if bucket_date else None
                
                # Keep bucket if it's for a different category OR if the date is before from_date
                if bucket_category_id != category_id_int or (bucket_date_str and bucket_date_str < from_date_str):
                    kept_rows.append(row)
                else:
                    # This bucket should be deleted
                    bucket_id = row.get('id')
                    if bucket_id and int(bucket_id) > 0:
                        deleted_bucket_ids.append(str(bucket_id))
            
            deleted_count = original_count - len(kept_rows)
            
            if deleted_count > 0:
                # Save back to Redis
                _redis_client.setex(
                    redis_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(kept_rows, cls=DecimalEncoder)
                )
                
                # Mark bucket IDs as pending deletion
                if deleted_bucket_ids:
                    pending_key = f"pending_deletes:{table_name}:{user_id}"
                    _redis_client.sadd(pending_key, *deleted_bucket_ids)
                    _redis_client.expire(pending_key, PERSISTENT_CACHE_TTL)
                
                # Mark as dirty
                dirty_key = f"dirty_tables:{user_id}"
                _redis_client.sadd(dirty_key, table_name)
                _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                
        
    except Exception as e:
        app.logger.error(f"Error deleting future buckets from {table_name} in Redis: {e}")


def _sync_expense_category_to_credit_accounts(user_id, category_name, display_order, group_id=None):
    """
    Sync an expense category to all credit accounts for a user.
    Creates a non-recurring c_expense_category for each credit account.
    
    This ensures expense categories are available across all credit accounts
    for unified category management.
    
    Args:
        user_id: User ID
        category_name: Name of the category
        display_order: Display order from the expense_category
        group_id: Optional group ID (currently not used for c_expense)
    
    Returns:
        Dictionary mapping account_id -> c_expense_category_id
    """
    created_map = {}  # account_id -> category_id
    
    # Get all credit accounts for this user
    accounts = _get_credit_accounts_from_redis(user_id)
    if accounts is None:
        # Fallback to MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(dictionary=True)
            cursor.execute("SELECT id FROM credit_accounts WHERE user_id = %s", (user_id,))
            accounts = cursor.fetchall()
            cursor.close()
    
    if not accounts:
        return created_map  # No credit accounts, nothing to sync
    
    for account in accounts:
        account_id = account.get('id')
        
        # Check if category already exists for this account (avoid duplicates)
        existing_categories = _get_categories_from_redis('c_expense_categories', user_id)
        if existing_categories:
            existing_cat = next(
                (cat for cat in existing_categories 
                 if cat.get('account_id') == account_id and cat.get('name') == category_name),
                None
            )
            if existing_cat:
                # Already exists, return the existing ID
                created_map[account_id] = existing_cat.get('id')
                continue
        
        # Get max display_order for this account's categories
        if existing_categories:
            account_cats = [cat for cat in existing_categories if cat.get('account_id') == account_id]
            max_order = max([cat.get('display_order', 0) for cat in account_cats], default=0)
        else:
            max_order = display_order  # Use the expense_category's display_order as fallback
        
        # Create c_expense category data (always non-recurring)
        c_expense_category = {
            'account_id': account_id,
            'name': category_name,
            'display_order': max_order + 1,
            'group_id': None,  # group_id not synced for now
            'is_recurring': 0,  # Always non-recurring when synced
            'no_end_date': 0,
            'hidden': 0,
            'is_bud': 0,
            'is_interest': 0,
            'is_auto_adjustment': 0
        }
        
        # Add to Redis
        new_id = _add_category_to_redis('c_expense_categories', user_id, c_expense_category)
        if new_id is not None:
            created_map[account_id] = new_id
        else:
            # Redis failed, try MySQL directly
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    INSERT INTO c_expense_categories 
                    (account_id, name, display_order, is_recurring, hidden, is_bud, is_interest, is_auto_adjustment)
                    VALUES (%s, %s, %s, 0, 0, 0, 0, 0)
                """, (account_id, category_name, max_order + 1))
                new_id = cursor.lastrowid
                conn.commit()
                cursor.close()
                created_map[account_id] = new_id
    
    return created_map


def _copy_expense_categories_to_new_credit_account(user_id, account_id):
    """
    Copy all existing expense categories to a newly created credit account.
    Skips system categories (is_credit_account=1, is_auto_adjustment=1) and
    categories that already exist for this account.
    
    Called when a new credit account is created (manual or Quiltt).
    
    Args:
        user_id: User ID
        account_id: The new credit account's ID (can be temp negative ID)
    
    Returns:
        Number of categories copied
    """
    # Get all expense categories for this user
    expense_categories = _get_categories_from_redis('expense_categories', user_id)
    if expense_categories is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("SELECT * FROM expense_categories WHERE user_id = %s", (user_id,))
            expense_categories = cursor.fetchall()
            cursor.close()
    
    if not expense_categories:
        return 0
    
    # Get existing c_expense categories to check for duplicates
    existing_c_cats = _get_categories_from_redis('c_expense_categories', user_id) or []
    existing_names_for_account = set(
        cat.get('name') for cat in existing_c_cats 
        if cat.get('account_id') == account_id
    )
    
    # Find max display_order for this account's categories
    account_cats = [cat for cat in existing_c_cats if cat.get('account_id') == account_id]
    max_order = max([cat.get('display_order', 0) for cat in account_cats], default=1)
    
    copied = 0
    for exp_cat in expense_categories:
        name = exp_cat.get('name')
        
        # Skip system categories
        if exp_cat.get('is_credit_account') == 1:
            continue
        if exp_cat.get('is_auto_adjustment') == 1:
            continue
        
        # Skip if already exists for this account
        if name in existing_names_for_account:
            continue
        
        max_order += 1
        _add_category_to_redis('c_expense_categories', user_id, {
            'account_id': account_id,
            'name': name,
            'display_order': max_order,
            'group_id': None,
            'is_recurring': 0,
            'no_end_date': 0,
            'hidden': 0,
            'is_bud': 0,
            'is_interest': 0,
            'is_auto_adjustment': 0
        })
        copied += 1
    
    if copied > 0:
        app.logger.info(f"[CATEGORY SYNC] Copied {copied} expense categories to credit account {account_id} for user {user_id}")
    
    return copied


def _sync_rename_to_credit_accounts(user_id, old_name, new_name):
    """
    Rename all c_expense_categories matching old_name to new_name across all credit accounts.
    Called when an expense_category is renamed.
    
    Args:
        user_id: User ID
        old_name: The original category name
        new_name: The new category name
    """
    renamed_count = 0
    
    # Update in Redis
    if app.config.get('REDIS_OK'):
        try:
            redis_key = f"c_expense_categories:v1:{user_id}"
            cached = _redis_client.get(redis_key)
            if cached:
                categories = json.loads(cached)
                for cat in categories:
                    if cat.get('name') == old_name and not cat.get('is_interest') and not cat.get('is_auto_adjustment'):
                        cat['name'] = new_name
                        renamed_count += 1
                if renamed_count > 0:
                    _redis_client.setex(redis_key, 604800, json.dumps(categories, cls=DecimalEncoder))
                    _redis_client.sadd(f"dirty_tables:{user_id}", 'c_expense_categories')
        except Exception as e:
            app.logger.error(f"Error syncing category rename to c_expense_categories in Redis: {e}")
    
    # Also update MySQL directly for consistency
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor()
        cursor.execute("""
            UPDATE c_expense_categories SET name = %s
            WHERE name = %s AND is_interest = 0 AND is_auto_adjustment = 0
              AND account_id IN (SELECT id FROM credit_accounts WHERE user_id = %s)
        """, (new_name, old_name, user_id))
        conn.commit()
        cursor.close()
    
    if renamed_count > 0:
        app.logger.info(f"[CATEGORY SYNC] Renamed '{old_name}' -> '{new_name}' in {renamed_count} c_expense categories for user {user_id}")


def _sync_delete_to_credit_accounts(user_id, category_name):
    """
    Delete all c_expense_categories matching category_name across all credit accounts.
    Called when an expense_category is deleted.
    Moves past entries to Uncategorized, deletes future entries, recurring, and buckets.
    
    Args:
        user_id: User ID
        category_name: The name of the category being deleted
    """
    if not category_name:
        return
    
    deleted_count = 0
    yesterday = date.today() - timedelta(days=1)
    
    # Get all c_expense_categories from Redis
    c_categories = _get_categories_from_redis('c_expense_categories', user_id)
    if not c_categories:
        return
    
    # Find matching categories (skip system categories)
    matching_cats = [cat for cat in c_categories 
                     if cat.get('name') == category_name 
                     and not cat.get('is_interest') 
                     and not cat.get('is_auto_adjustment')]
    
    if not matching_cats:
        return
    
    # Get all c_expense_entries from Redis
    entries = _get_entries_from_redis('c_expense_entries', user_id)
    
    # Group matching categories by account_id to find each account's Uncategorized
    account_ids = set(cat.get('account_id') for cat in matching_cats)
    
    # Build map of account_id -> Uncategorized category_id
    uncat_map = {}
    for cat in c_categories:
        if cat.get('name') == 'Uncategorized' and cat.get('account_id') in account_ids:
            uncat_map[cat.get('account_id')] = cat.get('id')
    
    # Move past entries to Uncategorized for each matching category
    if entries:
        entries_modified = False
        for match_cat in matching_cats:
            cat_id = int(match_cat.get('id'))
            acct_id = match_cat.get('account_id')
            uncat_id = uncat_map.get(acct_id)
            
            if not uncat_id:
                continue
            
            # Find past entries for this category
            past_entries = [e for e in entries 
                          if int(e.get('category_id', 0)) == cat_id 
                          and datetime.strptime(e.get('date'), '%Y-%m-%d').date() <= yesterday]
            
            for old_entry in past_entries:
                entry_date = old_entry.get('date')
                amount = float(old_entry.get('amount', 0))
                
                # Find existing Uncategorized entry for this date
                auto_entry = next((e for e in entries 
                                  if int(e.get('category_id', 0)) == int(uncat_id) 
                                  and e.get('date') == entry_date), None)
                
                if auto_entry:
                    new_amount = float(auto_entry.get('amount', 0)) + amount
                    for i, e in enumerate(entries):
                        if e.get('id') == auto_entry.get('id'):
                            entries[i]['amount'] = new_amount
                            entries[i]['processed'] = 1
                            break
                else:
                    temp_id = -int(time.time() * 1000000) - cat_id
                    new_entry = {
                        'id': temp_id,
                        'category_id': uncat_id,
                        'date': entry_date,
                        'amount': amount,
                        'recurring_id': None,
                        'is_bucket': 0,
                        'original_amount': None,
                        'processed': 1,
                        'bud_item_id': None
                    }
                    entries.append(new_entry)
                
                entries = [e for e in entries if e.get('id') != old_entry.get('id')]
                entries_modified = True
        
        if entries_modified:
            _set_entries_to_redis('c_expense_entries', user_id, entries)
    
    # Delete each matching category (handles entries, recurring, buckets, pending deletes)
    for match_cat in matching_cats:
        cat_id = match_cat.get('id')
        _delete_category_in_redis('c_expense_categories', user_id, cat_id)
        deleted_count += 1
    
    # Also remove recurring_c_expense records for deleted categories
    if app.config.get('REDIS_OK'):
        try:
            recurring_redis_key = f"recurring_c_expense:v1:{user_id}"
            recurring_data = _redis_client.get(recurring_redis_key)
            if recurring_data:
                recurring_list = json.loads(recurring_data)
                cat_ids = set(int(cat.get('id')) for cat in matching_cats)
                filtered = [r for r in recurring_list if int(r.get('category_id', 0)) not in cat_ids]
                if len(filtered) < len(recurring_list):
                    if len(filtered) == 0:
                        _redis_client.delete(recurring_redis_key)
                    else:
                        _redis_client.setex(recurring_redis_key, 604800, json.dumps(filtered, cls=DecimalEncoder))
                    _redis_client.sadd(f"dirty_tables:{user_id}", 'recurring_c_expense')
        except Exception as e:
            app.logger.error(f"[CATEGORY SYNC] Error removing recurring_c_expense for deleted categories: {e}")
    
    if deleted_count > 0:
        app.logger.info(f"[CATEGORY SYNC] Deleted '{category_name}' from {deleted_count} c_expense categories for user {user_id}")


def _category_name_exists(table_name, user_id, name, exclude_id=None):
    """
    Check if a category name already exists for a user (case-insensitive).
    
    Args:
        table_name: 'income_categories' or 'expense_categories'
        user_id: User ID
        name: Category name to check
        exclude_id: Category ID to exclude (for renames - don't match itself)
    
    Returns:
        True if a category with this name already exists
    """
    name_lower = name.strip().lower()
    
    # Try Redis first
    categories = _get_categories_from_redis(table_name, user_id)
    if categories is not None:
        for cat in categories:
            if cat.get('name', '').strip().lower() == name_lower:
                if exclude_id and int(cat.get('id')) == int(exclude_id):
                    continue
                return True
        return False
    
    # Fallback to MySQL
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor()
        if exclude_id:
            cursor.execute(
                f"SELECT COUNT(*) FROM {table_name} WHERE user_id = %s AND LOWER(TRIM(name)) = %s AND id != %s",
                (user_id, name_lower, exclude_id)
            )
        else:
            cursor.execute(
                f"SELECT COUNT(*) FROM {table_name} WHERE user_id = %s AND LOWER(TRIM(name)) = %s",
                (user_id, name_lower)
            )
        count = cursor.fetchone()[0]
        cursor.close()
        return count > 0


def _add_category_to_redis(table_name, user_id, category_data):
    """
    Add a new category to Redis cache.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (or account_id for c_expense_categories)
        category_data: Dictionary with category fields
    
    Returns:
        The new category ID (negative temporary ID for new categories)
    """
    if not app.config.get('REDIS_OK'):
        return None
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data or initialize empty list
        cached = _redis_client.get(redis_key)
        rows = json.loads(cached) if cached else []
        
        # Generate a negative temporary ID for the new category
        # (flush worker will replace with MySQL auto-increment ID)
        existing_ids = [int(row.get('id', 0)) for row in rows]
        min_id = min(existing_ids) if existing_ids else 0
        new_id = min_id - 1 if min_id <= 0 else -1
        
        # Add the ID to category data
        category_data['id'] = new_id
        
        # Add to array
        rows.append(category_data)
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty - user_id is now always the actual user_id for all category tables
        dirty_key = f"dirty_tables:{user_id}"
        
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        return new_id
        
    except Exception as e:
        app.logger.error(f"Error adding category to {table_name} in Redis: {e}")
        return None

def _add_categories_batch_to_redis(table_name, user_id, categories_list):
    """
    Add multiple categories to Redis in a SINGLE read-modify-write operation.
    This prevents race conditions with the background flush worker which can 
    overwrite categories added in separate _add_category_to_redis calls.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID
        categories_list: List of category data dictionaries
    
    Returns:
        List of new category IDs (negative temporary IDs), or empty list on failure.
        IDs are in the same order as categories_list.
    """
    if not app.config.get('REDIS_OK') or not categories_list:
        return []
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Single read
        cached = _redis_client.get(redis_key)
        rows = json.loads(cached) if cached else []
        
        # Generate sequential negative IDs for all new categories
        existing_ids = [int(row.get('id', 0)) for row in rows]
        min_id = min(existing_ids) if existing_ids else 0
        next_id = min_id - 1 if min_id <= 0 else -1
        
        new_ids = []
        for cat_data in categories_list:
            cat_data['id'] = next_id
            new_ids.append(next_id)
            rows.append(cat_data)
            next_id -= 1
        
        # Single write
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty once
        dirty_key = f"dirty_tables:{user_id}"
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        return new_ids
        
    except Exception as e:
        app.logger.error(f"Error batch-adding categories to {table_name} in Redis: {e}")
        return []


def _update_category_in_redis(table_name, user_id, category_id, updates):
    """
    Update a category in Redis cache.
    
    Args:
        table_name: 'income_categories', 'expense_categories', or 'c_expense_categories'
        user_id: User ID (now always user_id, even for c_expense_categories)
        category_id: ID of the category to update
        updates: Dictionary of fields to update
    """
    if not app.config.get('REDIS_OK'):
        return
    
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        
        # Get existing data
        cached = _redis_client.get(redis_key)
        if not cached:
            pass
            return
        
        rows = json.loads(cached)
        category_id_int = int(category_id)
        
        # Find and update the category
        updated = False
        for row in rows:
            if int(row.get('id')) == category_id_int:
                row.update(updates)
                updated = True
                break
        
        if not updated:
            pass
            return
        
        # Save back to Redis
        _redis_client.setex(
            redis_key,
            PERSISTENT_CACHE_TTL,
            json.dumps(rows, cls=DecimalEncoder)
        )
        
        # Mark as dirty - user_id is now always the actual user_id for all category tables
        dirty_key = f"dirty_tables:{user_id}"
        
        _redis_client.sadd(dirty_key, table_name)
        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        
    except Exception as e:
        app.logger.error(f"Error updating category in {table_name} in Redis: {e}")

def _trigger_ntropy_sync(user_id):
    """
    Trigger a sync of user's categories to Ntropy for transaction enrichment.
    This is a non-blocking operation - errors are logged but don't affect the caller.
    
    Call this after any category creation, update, or deletion.
    """
    try:
        from ntropy_utils import sync_user_categories_to_ntropy
        result = sync_user_categories_to_ntropy(user_id)
        if result:
            app.logger.info(f"[NTROPY] Synced categories to Ntropy for user {user_id}")
        else:
            app.logger.warning(f"[NTROPY] Sync returned False for user {user_id}")
    except Exception as e:
        app.logger.warning(f"[NTROPY] Failed to sync categories to Ntropy for user {user_id} (non-blocking): {e}")


