@app.route('/dashboard')
@login_required
def dashboard():
    now = datetime.now()
    fridays_by_month = {}

    # Fetch user data including goofy_week_mode, profile_picture, first_name, last_name, and balance_threshold
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)

        # Try Redis first
        user_data = None
        redis_key = f"users:v1:{current_user.id}"
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(redis_key)
                if cached:
                    user_data = json.loads(cached)
            except Exception as e:
                app.logger.error(f"[REDIS ERROR] dashboard user settings: {str(e)}")
        
        # Fallback to MySQL
        if not user_data:
            cursor.execute("""
                SELECT profile_picture, first_name, last_name, balance_threshold, goofy_week_mode, member_since, currency_type, landing_page
                FROM users
                WHERE id = %s
            """, (current_user.id,))
            user_data = cursor.fetchone()
            
            # Cache back to Redis
            if user_data and app.config.get('REDIS_OK'):
                try:
                    _redis_client.setex(
                        redis_key,
                        604800,  # 7 days TTL
                        json.dumps(user_data, default=str, cls=DecimalEncoder)
                    )
                except Exception as e:
                    app.logger.error(f"[REDIS ERROR] Failed to cache user data: {str(e)}")

        goofy_week_mode = bool(user_data.get('goofy_week_mode', False)) if user_data else False

        for month in range(1, 13):
            fridays = []
            cal = calendar.Calendar()
            for week in cal.monthdatescalendar(now.year, month):
                if goofy_week_mode:
                    friday = week[4]
                    if friday.month == month:
                        fridays.append(friday)
                else:
                    saturday = week[5]
                    if saturday.month == month:
                        fridays.append(saturday)
            fridays_by_month[calendar.month_name[month]] = fridays

        # Fetch income categories - try Redis first
        income_categories = _get_categories_from_redis('income_categories', current_user.id)
        if income_categories is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT id, name, is_auto_adjustment, hidden, is_recurring
                FROM income_categories
                WHERE user_id = %s
                ORDER BY display_order DESC
            """, (current_user.id,))
            income_categories = list(cursor.fetchall())
        else:
            # Sort by display_order descending (higher numbers first)
            income_categories = sorted(income_categories, key=lambda x: x.get('display_order', 0), reverse=True)

        # Fetch expense categories - try Redis first
        expense_categories = _get_categories_from_redis('expense_categories', current_user.id)
        if expense_categories is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT id, name, is_auto_adjustment, hidden, is_bud, is_recurring, is_credit_account
                FROM expense_categories
                WHERE user_id = %s
                ORDER BY display_order DESC
            """, (current_user.id,))
            expense_categories = list(cursor.fetchall())
        else:
            # Sort by display_order descending (higher numbers first)
            expense_categories = sorted(expense_categories, key=lambda x: x.get('display_order', 0), reverse=True)

        # Helper to get week key (start of week for goofy, end of week for normal)
        def get_week_key(date_val, goofy_week_mode):
            if isinstance(date_val, datetime):
                dt = date_val.date()
            elif isinstance(date_val, date):
                dt = date_val
            else:
                dt = datetime.strptime(date_val, '%Y-%m-%d').date()
            if goofy_week_mode:
                # Week starts Friday: find the most recent Friday (could be today)
                days_since_friday = (dt.weekday() - 4) % 7
                week_start = dt - timedelta(days=days_since_friday)
                return week_start.strftime('%Y-%m-%d')
            else:
                # Week ends Friday: find the next Friday (could be today)
                days_until_friday = (4 - dt.weekday()) % 7
                week_end = dt + timedelta(days=days_until_friday)
                return week_end.strftime('%Y-%m-%d')

        # --- AGGREGATE INCOME ENTRIES ---
        # Try Redis first
        raw_income_entries = _get_entries_from_redis('income_entries', current_user.id)
        if raw_income_entries is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT ie.id, ie.category_id, ie.date, ie.amount, ie.processed, ie.is_bucket, ie.original_amount, ie.original_date, ie.recurring_id
                FROM income_entries ie
                WHERE ie.category_id IN (SELECT id FROM income_categories WHERE user_id = %s)
            """, (current_user.id,))
            raw_income_entries = list(cursor.fetchall())
            raw_income_entries = _filter_pending_deletions('income_entries', current_user.id, raw_income_entries)
            # Update Redis cache
            _set_entries_to_redis('income_entries', current_user.id, raw_income_entries)
        else:
            pass

        # Get bucket records for tracking bucket vs non-bucket amounts
        income_bucket_records = _get_entries_from_redis('recurring_income_buckets', current_user.id) or []
        income_bucket_lookup = {}
        for bucket in income_bucket_records:
            cat_id = bucket.get('category_id')
            bucket_date = bucket.get('bucket_date')
            if cat_id is not None and bucket_date:
                income_bucket_lookup[(cat_id, bucket_date)] = {
                    'original_amount': float(bucket.get('original_amount', 0)),
                    'current_amount': float(bucket.get('amount', 0))
                }

        income_map = {}
        processed_map = {}
        pending_count_map = {}
        total_count_map = {}
        bucket_info_map = {}  # Track bucket info per cell
        for entry in raw_income_entries:
            week_key = get_week_key(entry['date'], goofy_week_mode)
            key = (entry['category_id'], week_key)
            income_map[key] = income_map.get(key, 0.0) + float(entry['amount'])
            if key not in processed_map:
                processed_map[key] = []
            processed_map[key].append(entry['processed'])
            total_count_map[key] = total_count_map.get(key, 0) + 1
            if entry.get('pending') == 1:
                pending_count_map[key] = pending_count_map.get(key, 0) + 1
            
            # Track bucket info
            if key not in bucket_info_map:
                bucket_info_map[key] = {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0}
            if entry.get('is_bucket') == 1:
                bucket_info_map[key]['has_bucket'] = True
                bucket_info_map[key]['bucket_amount'] += float(entry.get('amount', 0))
                bucket_info_map[key]['original_amount'] = float(entry.get('original_amount', 0)) if entry.get('original_amount') else float(entry.get('amount', 0))
                orig_date = entry.get('original_date')
                if orig_date:
                    if isinstance(orig_date, str):
                        orig_date = datetime.strptime(orig_date, '%Y-%m-%d').date()
                    elif isinstance(orig_date, datetime):
                        orig_date = orig_date.date()
                    days_late = (date.today() - orig_date).days
                    if days_late > bucket_info_map[key]['max_days_late']:
                        bucket_info_map[key]['max_days_late'] = days_late

        income_entries = []
        for key, total_amount in income_map.items():
            processed_list = processed_map[key]
            processed_flags = [_processed_flag_is_true(p) for p in processed_list]
            processed = 1 if processed_flags and all(processed_flags) else 0
            category_id, week_key = key
            bucket_info = bucket_info_map.get(key, {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0})
            entry_data = {
                'category_id': category_id,
                'date': week_key,
                'total_amount': total_amount,
                'processed': processed,
                'pending': 1 if pending_count_map.get(key) else 0,
                'pending_count': pending_count_map.get(key, 0),
                'total_count': total_count_map.get(key, 0)
            }
            if bucket_info['has_bucket']:
                entry_data['has_bucket'] = True
                entry_data['bucket_amount'] = bucket_info['bucket_amount']
                entry_data['original_amount'] = bucket_info['original_amount']
                if bucket_info['max_days_late'] > 0:
                    entry_data['max_days_late'] = bucket_info['max_days_late']
            income_entries.append(entry_data)

        # --- AGGREGATE EXPENSE ENTRIES ---
        # Try Redis first
        raw_expense_entries = _get_entries_from_redis('expense_entries', current_user.id)
        if raw_expense_entries is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT ee.id, ee.category_id, ee.date, ee.amount, ee.processed, ee.is_bucket, ee.original_amount, ee.original_date, ee.recurring_id, ee.bud_item_id
                FROM expense_entries ee
                WHERE ee.category_id IN (SELECT id FROM expense_categories WHERE user_id = %s)
            """, (current_user.id,))
            raw_expense_entries = list(cursor.fetchall())
            raw_expense_entries = _filter_pending_deletions('expense_entries', current_user.id, raw_expense_entries)
            # Update Redis cache
            _set_entries_to_redis('expense_entries', current_user.id, raw_expense_entries)
        else:
            pass

        expense_map = {}
        expense_processed_map = {}
        expense_pending_count_map = {}
        expense_total_count_map = {}
        expense_bucket_info_map = {}  # Track bucket info per cell
        for entry in raw_expense_entries:
            week_key = get_week_key(entry['date'], goofy_week_mode)
            key = (entry['category_id'], week_key)
            expense_map[key] = expense_map.get(key, 0.0) + float(entry['amount'])
            if key not in expense_processed_map:
                expense_processed_map[key] = []
            expense_processed_map[key].append(entry['processed'])
            expense_total_count_map[key] = expense_total_count_map.get(key, 0) + 1
            if entry.get('pending') == 1 or entry.get('auto_confirmed') == 1:
                expense_pending_count_map[key] = expense_pending_count_map.get(key, 0) + 1
            
            # Track bucket info
            if key not in expense_bucket_info_map:
                expense_bucket_info_map[key] = {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0}
            if entry.get('is_bucket') == 1:
                expense_bucket_info_map[key]['has_bucket'] = True
                expense_bucket_info_map[key]['bucket_amount'] += float(entry.get('amount', 0))
                expense_bucket_info_map[key]['original_amount'] = float(entry.get('original_amount', 0)) if entry.get('original_amount') else float(entry.get('amount', 0))
                orig_date = entry.get('original_date')
                if orig_date:
                    if isinstance(orig_date, str):
                        orig_date = datetime.strptime(orig_date, '%Y-%m-%d').date()
                    elif isinstance(orig_date, datetime):
                        orig_date = orig_date.date()
                    days_late = (date.today() - orig_date).days
                    if days_late > expense_bucket_info_map[key]['max_days_late']:
                        expense_bucket_info_map[key]['max_days_late'] = days_late

        expense_entries = []
        for key, total_amount in expense_map.items():
            processed_list = expense_processed_map[key]
            processed_flags = [_processed_flag_is_true(p) for p in processed_list]
            processed = 1 if processed_flags and all(processed_flags) else 0
            category_id, week_key = key
            bucket_info = expense_bucket_info_map.get(key, {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0})
            entry_data = {
                'category_id': category_id,
                'date': week_key,
                'total_amount': total_amount,
                'processed': processed,
                'pending': 1 if expense_pending_count_map.get(key) else 0,
                'pending_count': expense_pending_count_map.get(key, 0),
                'total_count': expense_total_count_map.get(key, 0)
            }
            if bucket_info['has_bucket']:
                entry_data['has_bucket'] = True
                entry_data['bucket_amount'] = bucket_info['bucket_amount']
                entry_data['original_amount'] = bucket_info['original_amount']
                if bucket_info['max_days_late'] > 0:
                    entry_data['max_days_late'] = bucket_info['max_days_late']
            expense_entries.append(entry_data)

        # --- AGGREGATE CA ENTRIES ---
        # Try Redis first
        raw_c_expense_entries = _get_entries_from_redis('c_expense_entries', current_user.id)
        if raw_c_expense_entries is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT cee.id, cee.category_id, cee.date, cee.amount, cee.processed, cee.is_bucket, cee.original_amount, cee.original_date
                FROM c_expense_entries cee
                JOIN c_expense_categories cec ON cee.category_id = cec.id
                JOIN credit_accounts ca ON cec.account_id = ca.id
                WHERE ca.user_id = %s
            """, (current_user.id,))
            raw_c_expense_entries = list(cursor.fetchall())
            raw_c_expense_entries = _filter_pending_deletions('c_expense_entries', current_user.id, raw_c_expense_entries)
            # Update Redis cache
            _set_entries_to_redis('c_expense_entries', current_user.id, raw_c_expense_entries)
        else:
            pass

        c_expense_map = {}
        c_expense_processed_map = {}
        c_expense_pending_count_map = {}
        c_expense_total_count_map = {}
        c_expense_bucket_info_map = {}  # Track bucket info per cell
        for entry in raw_c_expense_entries:
            week_key = get_week_key(entry['date'], goofy_week_mode)
            key = (entry['category_id'], week_key)
            c_expense_map[key] = c_expense_map.get(key, 0.0) + float(entry['amount'])
            if key not in c_expense_processed_map:
                c_expense_processed_map[key] = []
            c_expense_processed_map[key].append(entry['processed'])
            c_expense_total_count_map[key] = c_expense_total_count_map.get(key, 0) + 1
            if entry.get('pending') == 1 or entry.get('auto_confirmed') == 1:
                c_expense_pending_count_map[key] = c_expense_pending_count_map.get(key, 0) + 1
            
            # Track bucket info
            if key not in c_expense_bucket_info_map:
                c_expense_bucket_info_map[key] = {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0}
            if entry.get('is_bucket') == 1:
                c_expense_bucket_info_map[key]['has_bucket'] = True
                c_expense_bucket_info_map[key]['bucket_amount'] += float(entry.get('amount', 0))
                c_expense_bucket_info_map[key]['original_amount'] = float(entry.get('original_amount', 0)) if entry.get('original_amount') else float(entry.get('amount', 0))
                orig_date = entry.get('original_date')
                if orig_date:
                    if isinstance(orig_date, str):
                        orig_date = datetime.strptime(orig_date, '%Y-%m-%d').date()
                    elif isinstance(orig_date, datetime):
                        orig_date = orig_date.date()
                    days_late = (date.today() - orig_date).days
                    if days_late > c_expense_bucket_info_map[key]['max_days_late']:
                        c_expense_bucket_info_map[key]['max_days_late'] = days_late

        c_expense_entries = []
        for key, total_amount in c_expense_map.items():
            processed_list = c_expense_processed_map[key]
            processed_flags = [_processed_flag_is_true(p) for p in processed_list]
            processed = 1 if processed_flags and all(processed_flags) else 0
            category_id, week_key = key
            bucket_info = c_expense_bucket_info_map.get(key, {'has_bucket': False, 'bucket_amount': 0, 'original_amount': 0, 'max_days_late': 0})
            entry_data = {
                'category_id': category_id,
                'date': week_key,
                'total_amount': total_amount,
                'processed': processed,
                'pending': 1 if c_expense_pending_count_map.get(key) else 0,
                'pending_count': c_expense_pending_count_map.get(key, 0),
                'total_count': c_expense_total_count_map.get(key, 0)
            }
            if bucket_info['has_bucket']:
                entry_data['has_bucket'] = True
                entry_data['bucket_amount'] = bucket_info['bucket_amount']
                entry_data['original_amount'] = bucket_info['original_amount']
                if bucket_info['max_days_late'] > 0:
                    entry_data['max_days_late'] = bucket_info['max_days_late']
            c_expense_entries.append(entry_data)

        # Fetch all totals and remainders
        # Try Redis first
        totals_remainders = _get_totals_remainders_from_redis('totals_remainders', current_user.id)
        if totals_remainders is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT date, total_income, total_expenses, remainder, last_week_remainder
                FROM totals_remainders
                WHERE user_id = %s
            """, (current_user.id,))
            totals_remainders = cursor.fetchall()
            # Update Redis cache
            _set_totals_remainders_to_redis('totals_remainders', current_user.id, totals_remainders)
        else:
            pass

        # Fetch all savings entries for the user
        # Try Redis first
        savings_entries = _get_savings_entries_from_redis(current_user.id)
        if savings_entries is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT date, amount FROM savings_entries
                WHERE user_id = %s
                ORDER BY date ASC
            """, (current_user.id,))
            savings_entries = cursor.fetchall()
            # Update Redis cache
            _set_savings_entries_to_redis(current_user.id, savings_entries)
        else:
            pass

        # Fetch buds
        cursor.execute("""
            SELECT b.id, b.expense_category_id
            FROM buds b
            WHERE b.user_id = %s
        """, (current_user.id,))
        buds = cursor.fetchall()

        # Fetch credit accounts - try Redis first
        credit_accounts = _get_credit_accounts_from_redis(current_user.id)
        if credit_accounts is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT * FROM credit_accounts
                WHERE user_id = %s
                ORDER BY display_order DESC
            """, (current_user.id,))
            credit_accounts = list(cursor.fetchall())
        else:
            pass

        # Fetch c_expense_categories - try Redis first (all categories for user)
        c_expense_categories = []
        all_ca_categories = _get_categories_from_redis('c_expense_categories', current_user.id)
        if all_ca_categories is None:
            # Redis miss - fallback to MySQL for all accounts
            cursor.execute("""
                SELECT cec.*, ca.name AS account_name
                FROM c_expense_categories cec
                JOIN credit_accounts ca ON cec.account_id = ca.id
                WHERE ca.user_id = %s
                ORDER BY cec.display_order DESC, cec.id DESC
            """, (current_user.id,))
            c_expense_categories = list(cursor.fetchall())
        else:
            # Add account_name to each category from Redis
            account_names = {a['id']: a['name'] for a in credit_accounts}
            for cat in all_ca_categories:
                cat['account_name'] = account_names.get(cat.get('account_id'), '')
            c_expense_categories = all_ca_categories

        # Try Redis first for CA balances
        c_a_balances = _get_ca_balances_from_redis('c_a_balances', current_user.id)
        if c_a_balances is None:
            # Redis miss - fallback to MySQL
            cursor.execute("""
                SELECT * FROM c_a_balances
                WHERE account_id IN (
                    SELECT id FROM credit_accounts WHERE user_id = %s
                )
                ORDER BY date DESC
            """, (current_user.id,))
            c_a_balances = cursor.fetchall()
            # Update Redis cache
            _set_ca_balances_to_redis('c_a_balances', current_user.id, c_a_balances)
        else:
            pass

        cursor.close()

    profile_picture = user_data.get('profile_picture') if user_data else None
    first_name = user_data.get('first_name', '') if user_data else ''
    last_name = user_data.get('last_name', '') if user_data else ''
    balance_threshold = user_data.get('balance_threshold', 0) if user_data else 0
    member_since = user_data.get('member_since') if user_data else None
    currency_type = user_data.get('currency_type', 'USD') if user_data else 'USD'
    landing_page = user_data.get('landing_page', 'dashboard') if user_data else 'dashboard'

    # Get Quiltt account flags for entry locking
    quiltt_flags = get_user_quiltt_account_flags(current_user.id)
    quiltt_last_txn_date = get_quiltt_last_transaction_date(current_user.id)

    return render_template(
        'dashboard.html',
        fridays_by_month=fridays_by_month,
        profile_picture=profile_picture,
        first_name=first_name,
        last_name=last_name,
        income_categories=income_categories,
        expense_categories=expense_categories,
        income_entries=income_entries,
        expense_entries=expense_entries,
        totals_remainders=totals_remainders,
        calendar=calendar,
        now=now,
        balance_threshold=balance_threshold,
        goofy_week_mode=goofy_week_mode,
        savings_entries=savings_entries,
        member_since=member_since,
        landing_page=landing_page,
        buds=buds,
        currency_type=currency_type,
        credit_accounts=credit_accounts,
        c_expense_categories=c_expense_categories,
        c_expense_entries=c_expense_entries,
        c_a_balances=c_a_balances,
        quiltt_flags=quiltt_flags,
        quiltt_last_txn_date=quiltt_last_txn_date
    )


@app.route('/get-recurring-id-for-category', methods=['POST'])
@login_required
def get_recurring_id_for_category():
    """Look up the recurring record ID for a given category ID and type."""
    data = request.get_json()
    category_id = data.get('category_id')
    category_type = data.get('category_type')  # 'income', 'expense', 'ca'

    if not category_id or not category_type:
        return jsonify({'status': 'error', 'message': 'Missing fields'}), 400

    try:
        table_map = {
            'income': 'recurring_income',
            'expense': 'recurring_expense',
            'ca': 'recurring_c_expense'
        }
        table_name = table_map.get(category_type)
        if not table_name:
            return jsonify({'status': 'error', 'message': 'Invalid category type'}), 400

        # Try Redis first
        cached = _get_recurring_from_redis(table_name, current_user.id)
        if cached:
            for rec in cached:
                if int(rec.get('category_id', 0)) == int(category_id):
                    return jsonify({'status': 'success', 'recurring_id': rec.get('id')})

        # Fallback to MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute(f"""
                SELECT id FROM {table_name} WHERE category_id = %s AND user_id = %s LIMIT 1
            """, (category_id, current_user.id))
            row = cursor.fetchone()
            cursor.close()
            if row:
                return jsonify({'status': 'success', 'recurring_id': row[0]})

        return jsonify({'status': 'error', 'message': 'Recurring record not found'}), 404

    except Exception as e:
        app.logger.error(f"Error looking up recurring ID: {e}")
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/get_total_income', methods=['GET'])
@login_required
def get_total_income():
    date = request.args.get('date')
    if not date:
        return jsonify({'status': 'error', 'message': 'Missing date parameter'}), 400

    try:
        # Try Redis first
        cached_data = _get_totals_remainders_from_redis('totals_remainders', current_user.id)
        if cached_data:
            # Find the matching date in cached data
            for row in cached_data:
                if row.get('date') == date:
                    total_income = row.get('total_income', 0)
                    return jsonify({'status': 'success', 'total_income': total_income})
        
        # Fallback to MySQL if not in Redis
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)

            # Fetch total_income from totals_remainders table
            cursor.execute("""
                SELECT total_income
                FROM totals_remainders
                WHERE user_id = %s AND date = %s
            """, (current_user.id, date))
            
            result = cursor.fetchone()
            total_income = result['total_income'] if result else 0
            cursor.close()
        
        return jsonify({'status': 'success', 'total_income': total_income})
    
    except Exception as e:
        return jsonify({'status': 'error', 'message': 'Internal Server Error'}), 500


