@app.route('/get_week_totals_batch', methods=['GET'])
@login_required
def get_week_totals_batch():
    """
    Batch endpoint to get all totals/remainders for multiple dates in a single request.
    This replaces multiple calls to get_total_income, get_total_expenses, get_remainder, get_last_remainder.
    
    Query params:
        dates: comma-separated list of dates (e.g., "2025-12-06,2025-12-13,2025-12-20,2025-12-27")
        
    Returns:
        {
            "status": "success",
            "data": {
                "2025-12-06": {"total_income": 100, "total_expenses": 50, "remainder": 50, "last_week_remainder": 0},
                ...
            }
        }
    """
    dates_param = request.args.get('dates', '')
    if not dates_param:
        return jsonify({'status': 'error', 'message': 'Missing dates parameter'}), 400
    
    dates = [d.strip() for d in dates_param.split(',') if d.strip()]
    
    # Dates come in as-is (Thursday in goofy mode, Friday in normal mode)
    # since weekly data is now stored on the correct day in both modes
    lookup_map = {d: d for d in dates}
    
    lookup_dates = list(lookup_map.keys())
    
    try:
        result_data = {}
        
        # Get all totals from Redis (single call)
        cached_data = _get_totals_remainders_from_redis('totals_remainders', current_user.id)
        
        if cached_data:
            # Build a lookup dict for O(1) access
            cached_lookup = {row.get('date'): row for row in cached_data}
            
            for ldate in lookup_dates:
                original_date = lookup_map[ldate]
                if ldate in cached_lookup:
                    row = cached_lookup[ldate]
                    result_data[original_date] = {
                        'total_income': float(row.get('total_income', 0) or 0),
                        'total_expenses': float(row.get('total_expenses', 0) or 0),
                        'remainder': float(row.get('remainder', 0) or 0),
                        'last_week_remainder': float(row.get('last_week_remainder', 0) or 0)
                    }
                else:
                    result_data[original_date] = {
                        'total_income': 0,
                        'total_expenses': 0,
                        'remainder': 0,
                        'last_week_remainder': 0
                    }
        else:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                placeholders = ','.join(['%s'] * len(lookup_dates))
                cursor.execute(f"""
                    SELECT date, total_income, total_expenses, remainder, last_week_remainder
                    FROM totals_remainders
                    WHERE user_id = %s AND date IN ({placeholders})
                """, [current_user.id] + lookup_dates)
                
                rows = cursor.fetchall()
                cursor.close()
                
                # Build result from MySQL data
                mysql_lookup = {str(row['date']): row for row in rows}
                for ldate in lookup_dates:
                    original_date = lookup_map[ldate]
                    if ldate in mysql_lookup:
                        row = mysql_lookup[ldate]
                        result_data[original_date] = {
                            'total_income': float(row.get('total_income', 0) or 0),
                            'total_expenses': float(row.get('total_expenses', 0) or 0),
                            'remainder': float(row.get('remainder', 0) or 0),
                            'last_week_remainder': float(row.get('last_week_remainder', 0) or 0)
                        }
                    else:
                        result_data[original_date] = {
                            'total_income': 0,
                            'total_expenses': 0,
                            'remainder': 0,
                            'last_week_remainder': 0
                        }
        
        return jsonify({'status': 'success', 'data': result_data})
        
    except Exception as e:
        app.logger.error(f"[get_week_totals_batch] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Internal Server Error'}), 500


@app.route('/get_ca_balances_batch', methods=['GET'])
@login_required
def get_ca_balances_batch():
    """
    Batch endpoint to get credit account balances for multiple dates and accounts.
    
    Query params:
        dates: comma-separated list of dates
        account_ids: comma-separated list of account IDs (optional, defaults to all user's accounts)
        
    Returns:
        {
            "status": "success",
            "data": {
                "account_id": {
                    "date": balance,
                    ...
                },
                ...
            }
        }
    """
    dates_param = request.args.get('dates', '')
    account_ids_param = request.args.get('account_ids', '')
    
    if not dates_param:
        return jsonify({'status': 'error', 'message': 'Missing dates parameter'}), 400
    
    dates = [d.strip() for d in dates_param.split(',') if d.strip()]
    
    # Dates come in as-is (Thursday in goofy mode, Friday in normal mode)
    # since weekly CA data is now stored on the correct day in both modes
    lookup_map = {d: d for d in dates}
    
    lookup_dates = list(lookup_map.keys())
    
    try:
        result_data = {}
        
        # Get all CA balances from Redis
        cached_data = _get_ca_balances_from_redis('c_a_balances', current_user.id)
        
        if cached_data:
            # Group by account_id
            for row in cached_data:
                account_id = str(row.get('account_id'))
                row_date = row.get('date')
                
                if account_id not in result_data:
                    result_data[account_id] = {}
                
                if row_date in lookup_dates:
                    original_date = lookup_map[row_date]
                    result_data[account_id][original_date] = float(row.get('balance', 0) or 0)
            
            # Fill in missing dates with 0
            for account_id in result_data:
                for ldate in lookup_dates:
                    original_date = lookup_map[ldate]
                    if original_date not in result_data[account_id]:
                        result_data[account_id][original_date] = 0
        else:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                placeholders = ','.join(['%s'] * len(lookup_dates))
                cursor.execute(f"""
                    SELECT cab.account_id, cab.date, cab.balance
                    FROM c_a_balances cab
                    JOIN credit_accounts ca ON cab.account_id = ca.id
                    WHERE ca.user_id = %s AND cab.date IN ({placeholders})
                """, [current_user.id] + lookup_dates)
                
                rows = cursor.fetchall()
                cursor.close()
                
                for row in rows:
                    account_id = str(row['account_id'])
                    row_date = str(row['date'])
                    original_date = lookup_map.get(row_date, row_date)
                    
                    if account_id not in result_data:
                        result_data[account_id] = {}
                    
                    result_data[account_id][original_date] = float(row.get('balance', 0) or 0)
        
        return jsonify({'status': 'success', 'data': result_data})
        
    except Exception as e:
        app.logger.error(f"[get_ca_balances_batch] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Internal Server Error'}), 500


@app.route('/update_income_order', methods=['POST'])
@login_required
def update_income_order():
    order_data = request.json['order']
    user_id = current_user.id

    # Build lookup: category id → new display_order
    order_by_id = {int(item['id']): int(item['order']) for item in order_data if item.get('id')}

    try:
        redis_key = f"income_categories:v1:{user_id}"
        cached = _redis_client.get(redis_key) if app.config.get('REDIS_OK') else None
        if cached:
            categories = json.loads(cached)
            for cat in categories:
                cat_id = int(cat.get('id', 0))
                if cat_id in order_by_id:
                    cat['display_order'] = order_by_id[cat_id]
            _redis_client.setex(redis_key, 604800, json.dumps(categories, cls=DecimalEncoder))
            _redis_client.sadd(f"dirty_tables:{user_id}", 'income_categories')
        else:
            # Redis miss — fall back to direct MySQL update
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                for item in order_data:
                    cursor.execute("""
                        UPDATE income_categories SET display_order = %s
                        WHERE user_id = %s AND id = %s
                    """, (int(item['order']), user_id, int(item['id'])))
                conn.commit()
                cursor.close()
    except Exception as e:
        app.logger.error(f"[update_income_order] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Failed to save order'}), 500

    return jsonify({'status': 'success'})

@app.route('/update_expense_order', methods=['POST'])
@login_required
def update_expense_order():
    order_data = request.json['order']
    user_id = current_user.id

    # Build lookup: category id → new display_order (and name for c_expense sync)
    order_by_id = {int(item['id']): int(item['order']) for item in order_data if item.get('id')}
    order_by_name = {item['name']: int(item['order']) for item in order_data if item.get('name')}

    try:
        if not app.config.get('REDIS_OK'):
            raise Exception('Redis unavailable')

        # Update expense_categories in Redis
        exp_key = f"expense_categories:v1:{user_id}"
        cached = _redis_client.get(exp_key)
        if cached:
            categories = json.loads(cached)
            for cat in categories:
                cat_id = int(cat.get('id', 0))
                if cat_id in order_by_id and not cat.get('is_credit_account'):
                    cat['display_order'] = order_by_id[cat_id]
            _redis_client.setex(exp_key, 604800, json.dumps(categories, cls=DecimalEncoder))
            _redis_client.sadd(f"dirty_tables:{user_id}", 'expense_categories')

        # Sync display_order to c_expense_categories in Redis (by name match)
        ca_key = f"c_expense_categories:v1:{user_id}"
        ca_cached = _redis_client.get(ca_key)
        if ca_cached:
            c_categories = json.loads(ca_cached)
            changed = False
            for cat in c_categories:
                if cat.get('is_interest') or cat.get('is_auto_adjustment'):
                    continue
                new_order = order_by_name.get(cat.get('name'))
                if new_order is not None:
                    cat['display_order'] = new_order
                    changed = True
            if changed:
                _redis_client.setex(ca_key, 604800, json.dumps(c_categories, cls=DecimalEncoder))
                _redis_client.sadd(f"dirty_tables:{user_id}", 'c_expense_categories')

        if not cached and not ca_cached:
            # Full Redis miss — fall back to direct MySQL update
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                for item in order_data:
                    cursor.execute("""
                        UPDATE expense_categories SET display_order = %s
                        WHERE user_id = %s AND id = %s AND is_credit_account = 0
                    """, (int(item['order']), user_id, int(item['id'])))
                cursor.execute("SELECT id FROM credit_accounts WHERE user_id = %s", (user_id,))
                acct_rows = cursor.fetchall()
                for item in order_data:
                    for acct_row in acct_rows:
                        acct_id = acct_row[0] if isinstance(acct_row, tuple) else acct_row['id']
                        cursor.execute("""
                            UPDATE c_expense_categories SET display_order = %s
                            WHERE account_id = %s AND name = %s
                              AND is_interest = 0 AND is_auto_adjustment = 0
                        """, (int(item['order']), acct_id, item['name']))
                conn.commit()
                cursor.close()
    except Exception as e:
        app.logger.error(f"[update_expense_order] Error: {e}")
        return jsonify({'status': 'error', 'message': 'Failed to save order'}), 500

    return jsonify({'status': 'success'})

