@app.route('/update_credit_account_order', methods=['POST'])
@login_required
def update_credit_account_order():
    """Reorder credit accounts by updating display_order in Redis (flushed to MySQL).
    Also syncs payment category display_order in expense_categories to match."""
    order_data = request.json.get('order', [])
    user_id = current_user.id

    if not order_data:
        return jsonify({'status': 'error', 'message': 'No order data provided'}), 400

    try:
        # Update Redis in-place
        accounts = _get_credit_accounts_from_redis(user_id)
        if accounts:
            # Build lookup: account_id → new display_order
            order_map = {int(item['id']): int(item['order']) for item in order_data}
            # Build lookup: account_id → account name (for payment category sync)
            account_name_map = {}
            for account in accounts:
                acct_id = int(account.get('id', 0))
                if acct_id in order_map:
                    account['display_order'] = order_map[acct_id]
                    account_name_map[acct_id] = account.get('name', '')

            # Sort by new display_order DESC and save back
            accounts.sort(key=lambda a: int(a.get('display_order', 0)), reverse=True)
            redis_key = f"credit_accounts:v1:{user_id}"
            _redis_client.setex(redis_key, PERSISTENT_CACHE_TTL, json.dumps(accounts, cls=DecimalEncoder))
            _redis_client.sadd(f"dirty_tables:{user_id}", 'credit_accounts')
            _redis_client.expire(f"dirty_tables:{user_id}", PERSISTENT_CACHE_TTL)

            # Sync payment category display_order in expense_categories to match credit account order
            expense_categories = _get_categories_from_redis('expense_categories', user_id)
            if expense_categories:
                payment_updated = False
                for cat in expense_categories:
                    if cat.get('is_credit_account') != 1:
                        continue
                    ca_id = cat.get('credit_account_id')
                    if ca_id is not None and int(ca_id) in order_map:
                        cat['display_order'] = order_map[int(ca_id)]
                        payment_updated = True
                if payment_updated:
                    _redis_client.setex(
                        f"expense_categories:v1:{user_id}",
                        PERSISTENT_CACHE_TTL,
                        json.dumps(expense_categories, cls=DecimalEncoder)
                    )
                    _redis_client.sadd(f"dirty_tables:{user_id}", 'expense_categories')
                    _redis_client.expire(f"dirty_tables:{user_id}", PERSISTENT_CACHE_TTL)

        return jsonify({'status': 'success'})
    except Exception as e:
        app.logger.error(f"Error updating credit account order: {e}")
        return jsonify({'status': 'error', 'message': str(e)}), 500

def _get_updated_buckets_from_redis(table_name, user_id, category_id, aggregation='week', specific_date=None):
    """
    Get bucket entries from Redis for the given category.
    For aggregated views, calculates the total for each period (bucket + manual entries).
    
    Args:
        table_name: 'income_entries', 'expense_entries', or 'c_expense_entries'
        user_id: User ID
        category_id: Category ID
        aggregation: 'week' for dashboard.html, 'month' for dashboard_3m.html, 'day' for dashboard_d.html
        specific_date: If provided, only return the bucket for the period containing this date
    
    Returns list with id, category_id, amount (period total), and date (period key).
    """
    try:
        redis_key = f"{table_name}:v1:{user_id}"
        redis_data = _redis_client.get(redis_key) if _redis_client else None
        if not redis_data:
            return []
            
        entries = json.loads(redis_data)
        
        # Get user's goofy_week_mode setting (Redis first, then MySQL)
        goofy_week_mode = None
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(f"users:v1:{user_id}")
                if cached:
                    user_data = json.loads(cached)
                    if 'goofy_week_mode' in user_data:
                        goofy_week_mode = bool(int(user_data['goofy_week_mode']))
            except Exception:
                pass
        if goofy_week_mode is None:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("SELECT goofy_week_mode FROM users WHERE id = %s", (user_id,))
                user_row = cursor.fetchone()
                goofy_week_mode = bool(user_row['goofy_week_mode']) if user_row else False
                cursor.close()
        
        # Helper to get period key based on aggregation type
        def get_period_key(date_val):
            if isinstance(date_val, str):
                dt = datetime.strptime(date_val, '%Y-%m-%d').date()
            else:
                dt = date_val
            
            if aggregation == 'month':
                # Return last day of month
                last_day = calendar.monthrange(dt.year, dt.month)[1]
                month_end = dt.replace(day=last_day)
                return month_end.strftime('%Y-%m-%d')
            elif aggregation == 'week':
                if goofy_week_mode:
                    # Goofy mode: week is Fri→Thu, period key is Thursday (week end)
                    days_since_friday = (dt.weekday() - 4) % 7
                    week_start = dt - timedelta(days=days_since_friday)
                    week_end = week_start + timedelta(days=6)  # Thursday
                    return week_end.strftime('%Y-%m-%d')
                else:
                    # Normal mode: week is Sat→Fri, period key is Friday (week end)
                    days_until_friday = (4 - dt.weekday()) % 7
                    week_end = dt + timedelta(days=days_until_friday)
                    return week_end.strftime('%Y-%m-%d')
            else:  # day
                # Return the date itself for daily view
                return dt.strftime('%Y-%m-%d')
        
        # Group all entries by period for this category
        period_totals = {}
        bucket_ids = {}
        bucket_original_amounts = {}
        
        
        for entry in entries:
            if entry.get('category_id') == int(category_id):
                entry_date = entry.get('date')
                period_key = get_period_key(entry_date)
                amount = float(entry.get('amount', 0))
                
                if period_key not in period_totals:
                    period_totals[period_key] = 0
                period_totals[period_key] += amount
                
                # Track bucket ID and original_amount for this period (if this is a bucket entry)
                if entry.get('is_bucket') == 1:
                    bucket_ids[period_key] = entry.get('id')
                    bucket_original_amounts[period_key] = float(entry.get('original_amount') or 0)
        
        # Return aggregated period totals (only for periods that have a bucket)
        buckets = []
        
        # Also check bucket records to find periods where bucket was deleted (amount <= 0)
        # This ensures frontend knows to remove the bucket from UI
        from recurring_bucket_manager import get_bucket_table_for_entry_table
        bucket_table = get_bucket_table_for_entry_table(table_name)
        deleted_bucket_periods = {}  # Dict to store period_key -> original_amount
        
        if bucket_table:
            # All bucket tables now use user_id consistently
            bucket_records_key = f"{bucket_table}:v1:{user_id}"
            bucket_records_data = _redis_client.get(bucket_records_key) if _redis_client else None
            if bucket_records_data:
                bucket_records = json.loads(bucket_records_data)
                for record in bucket_records:
                    if record.get('category_id') == int(category_id):
                        record_date = record.get('bucket_date')
                        record_amount = float(record.get('amount', 0))
                        record_original_amount = float(record.get('original_amount', 0))
                        period_key = get_period_key(record_date)
                        
                        # If bucket record exists but has amount <= 0 and no bucket entry exists
                        if record_amount <= 0 and period_key not in bucket_ids:
                            deleted_bucket_periods[period_key] = record_original_amount
        
        # If specific_date is provided, only return the bucket for that period
        if specific_date:
            target_period_key = get_period_key(specific_date)
            if target_period_key in bucket_ids:
                buckets.append({
                    'id': bucket_ids[target_period_key],
                    'category_id': int(category_id),
                    'amount': period_totals[target_period_key],
                    'original_amount': bucket_original_amounts.get(target_period_key, 0),
                    'date': target_period_key
                })
            elif target_period_key in deleted_bucket_periods:
                # Return bucket with amount=0 to signal deletion, but preserve original_amount for progress bar
                buckets.append({
                    'id': None,
                    'category_id': int(category_id),
                    'amount': 0,
                    'original_amount': deleted_bucket_periods[target_period_key],
                    'date': target_period_key
                })
            else:
                pass
        else:
            # Return all buckets (both existing and deleted)
            for period_key in bucket_ids.keys():
                buckets.append({
                    'id': bucket_ids[period_key],
                    'category_id': int(category_id),
                    'amount': period_totals[period_key],  # Total for the period (bucket + manual)
                    'original_amount': bucket_original_amounts.get(period_key, 0),
                    'date': period_key
                })
            
            # Also include deleted buckets (with their original_amount for progress bar)
            for period_key, orig_amount in deleted_bucket_periods.items():
                buckets.append({
                    'id': None,
                    'category_id': int(category_id),
                    'amount': 0,
                    'original_amount': orig_amount,
                    'date': period_key
                })
        
        return buckets
        
    except Exception as e:
        app.logger.error(f"[GET BUCKETS] Error getting buckets: {e}")
        app.logger.exception(e)
    return []

@app.route('/update-entry', methods=['POST'])
@login_required
def update_entry():
    data = request.json
    category_id = data.get('category_id')
    date = data.get('date')
    amount = data.get('amount')
    entry_type = data.get('type')
    entry_id = data.get('entry_id')  # Optional: specific entry ID for precise targeting
    

    if not category_id or not date or amount is None:
        return jsonify({"status": "error", "message": "Missing required parameters"}), 400

    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)

        ca_triggered = False
        payment_category_name = None
        account_id = None

        if entry_type == 'income':
            table_name = 'income_entries'
            category_table = 'income_categories'
        elif entry_type == 'expense':
            table_name = 'expense_entries'
            category_table = 'expense_categories'
        elif entry_type == 'ca':
            table_name = 'c_expense_entries'
            category_table = 'c_expense_categories'
        else:
            cursor.close()
            return jsonify({"status": "error", "message": "Invalid entry type"}), 400

        # User isolation for CA: join through credit_accounts
        if entry_type == 'ca':
            cursor.execute(f"""
                SELECT cec.id
                FROM c_expense_categories cec
                JOIN credit_accounts ca ON cec.account_id = ca.id
                WHERE cec.id = %s AND ca.user_id = %s
            """, (category_id, current_user.id))
            cat_row = cursor.fetchone()
            if not cat_row:
                cursor.close()
                return jsonify({"status": "error", "message": "Invalid category_id for this entry type"}), 400
        else:
            cursor.execute(f"SELECT * FROM {category_table} WHERE id = %s AND user_id = %s", (category_id, current_user.id))
            cat_row = cursor.fetchone()
            if not cat_row:
                cursor.close()
                return jsonify({"status": "error", "message": "Invalid category_id for this entry type"}), 400
        
        # Make a copy of cat_row data before closing cursor
        cat_data = dict(cat_row) if cat_row else {}
        cursor.close()
    
    # Write to Redis only - flush worker will persist to MySQL
    # If amount is 0, delete the entry instead of updating
    if float(amount) == 0:
        # Before deleting, get the current amount from Redis to restore bucket properly
        old_entry_amount = None
        
        # Get entries from Redis
        existing_data = _get_entries_from_redis(table_name, current_user.id)
        if existing_data is None:
            # Load from MySQL if not in Redis
            existing_data = []
            with get_db_pool().get_connection() as conn:
                cursor_check = conn.cursor(pymysql.cursors.DictCursor)
                if entry_type == 'income':
                    cursor_check.execute("""
                        SELECT ie.* FROM income_entries ie
                        JOIN income_categories ic ON ie.category_id = ic.id
                        WHERE ic.user_id = %s
                    """, (current_user.id,))
                elif entry_type == 'expense':
                    cursor_check.execute("""
                        SELECT ee.* FROM expense_entries ee
                        JOIN expense_categories ec ON ee.category_id = ec.id
                        WHERE ec.user_id = %s
                    """, (current_user.id,))
                elif entry_type == 'ca':
                    cursor_check.execute("""
                        SELECT cee.* FROM c_expense_entries cee
                        JOIN c_expense_categories cec ON cee.category_id = cec.id
                        JOIN credit_accounts ca ON cec.account_id = ca.id
                        WHERE ca.user_id = %s
                    """, (current_user.id,))
                existing_data = list(cursor_check.fetchall())
                cursor_check.close()
            existing_data = _filter_pending_deletions(table_name, current_user.id, existing_data)
        
        # Find the entry being deleted - match by ID if available, otherwise by category+date
        for entry in existing_data:
            if entry_id is not None:
                if entry.get('id') is not None and str(entry.get('id')) == str(entry_id):
                    old_entry_amount = entry.get('amount')
                    break
            elif str(entry.get('category_id')) == str(category_id) and str(entry.get('date')) == str(date):
                old_entry_amount = entry.get('amount')
                break
        
        # If there's an old entry in a recurring category, restore its bucket before deleting
        if old_entry_amount is not None and float(old_entry_amount) > 0:
            try:
                # Get recurring info for this category
                with get_db_pool().get_connection() as conn:
                    cursor_rec = conn.cursor(pymysql.cursors.DictCursor)
                    if entry_type == 'income':
                        cursor_rec.execute("""
                            SELECT cadence_unit, cadence_interval, start_date, end_date,
                                   weekdays, monthly_days, yearly_day, yearly_month, amount as original_amount
                            FROM recurring_income
                            WHERE category_id = %s AND user_id = %s
                        """, (category_id, current_user.id))
                    elif entry_type == 'expense':
                        cursor_rec.execute("""
                            SELECT cadence_unit, cadence_interval, start_date, end_date,
                                   weekdays, monthly_days, yearly_day, yearly_month, amount as original_amount
                            FROM recurring_expense
                            WHERE category_id = %s AND user_id = %s
                        """, (category_id, current_user.id))
                    elif entry_type == 'ca':
                        cursor_rec.execute("""
                            SELECT cadence_unit, cadence_interval, start_date, end_date,
                                   weekdays, monthly_days, yearly_day, yearly_month, amount as original_amount
                            FROM recurring_c_expense
                            WHERE category_id = %s
                        """, (category_id,))
                    recurring_info = cursor_rec.fetchone()
                    cursor_rec.close()
                
                entry_date = date
                if isinstance(entry_date, str):
                    entry_date = date.fromisoformat(entry_date)
                
                if recurring_info:
                    from bucket_utils import restore_bucket_for_deleted_entry
                    restore_bucket_for_deleted_entry(
                        table_name,
                        category_id,
                        entry_date,
                        Decimal(str(old_entry_amount)),
                        current_user.id,
                        recurring_info
                    )
                else:
                    from bucket_utils import restore_bucket_for_deleted_entry_v2
                    restore_bucket_for_deleted_entry_v2(
                        table_name,
                        category_id,
                        Decimal(str(old_entry_amount)),
                        current_user.id
                    )
            except Exception as e:
                app.logger.error(f"[BUCKET RESTORE DELETE] Error restoring bucket: {e}")
                app.logger.exception(e)
        
        _delete_entry_in_redis(table_name, current_user.id, category_id, date, date, specific_entry_id=entry_id)
    else:
        # When modifying an existing entry, we need to:
        # 1. Restore the old amount to the bucket (if it was depleting a bucket)
        # 2. Deplete the new amount from the bucket
        # This ensures the bucket reflects the net change, not a double depletion
        
        # First, check if there's an existing entry
        existing_data = _get_entries_from_redis(table_name, current_user.id)
        if existing_data is None:
            existing_data = []
            with get_db_pool().get_connection() as conn:
                cursor_existing = conn.cursor(pymysql.cursors.DictCursor)
                if entry_type == 'income':
                    cursor_existing.execute("""
                        SELECT ie.* FROM income_entries ie
                        JOIN income_categories ic ON ie.category_id = ic.id
                        WHERE ic.user_id = %s
                    """, (current_user.id,))
                elif entry_type == 'expense':
                    cursor_existing.execute("""
                        SELECT ee.* FROM expense_entries ee
                        JOIN expense_categories ec ON ee.category_id = ec.id
                        WHERE ec.user_id = %s
                    """, (current_user.id,))
                elif entry_type == 'ca':
                    cursor_existing.execute("""
                        SELECT cee.* FROM c_expense_entries cee
                        JOIN c_expense_categories cec ON cee.category_id = cec.id
                        JOIN credit_accounts ca ON cec.account_id = ca.id
                        WHERE ca.user_id = %s
                    """, (current_user.id,))
                existing_data = list(cursor_existing.fetchall())
                cursor_existing.close()
            existing_data = _filter_pending_deletions(table_name, current_user.id, existing_data)
        
        existing_entry = None
        app.logger.info(f"[UPDATE-ENTRY DEBUG] Looking for existing entry: entry_id={entry_id}, category_id={category_id}, date={date}, type={entry_type}")
        app.logger.info(f"[UPDATE-ENTRY DEBUG] existing_data has {len(existing_data)} entries")
        for entry in existing_data:
            if entry_id is not None:
                if entry.get('id') is not None and str(entry.get('id')) == str(entry_id):
                    existing_entry = entry
                    app.logger.info(f"[UPDATE-ENTRY DEBUG] Found by entry_id={entry_id}: is_bucket={entry.get('is_bucket')}, amount={entry.get('amount')}, original_amount={entry.get('original_amount')}")
                    break
            elif str(entry.get('category_id')) == str(category_id) and str(entry.get('date')) == str(date):
                existing_entry = entry
                app.logger.info(f"[UPDATE-ENTRY DEBUG] Found by cat+date: id={entry.get('id')}, is_bucket={entry.get('is_bucket')}, amount={entry.get('amount')}")
                break
        
        if existing_entry is None:
            app.logger.info(f"[UPDATE-ENTRY DEBUG] NO existing entry found! entry_id={entry_id}")
            # Log first few entries for debugging
            for i, e in enumerate(existing_data[:5]):
                app.logger.info(f"[UPDATE-ENTRY DEBUG] entry[{i}]: id={e.get('id')} (type={type(e.get('id')).__name__}), cat={e.get('category_id')}, date={e.get('date')}, is_bucket={e.get('is_bucket')}")
        
        # Check for bucket entries and deplete them
        try:
            # Get recurring info for this category to determine cadence from Redis
            if entry_type == 'income':
                recurring_info = _get_recurring_info_from_redis('recurring_income', current_user.id, category_id)
            elif entry_type == 'expense':
                recurring_info = _get_recurring_info_from_redis('recurring_expense', current_user.id, category_id)
            elif entry_type == 'ca':
                recurring_info = _get_recurring_info_from_redis('recurring_c_expense', current_user.id, category_id)
            else:
                recurring_info = None
            
            
            # Bucket entry edit — update the bucket record directly (no recurring_info needed)
            if existing_entry and existing_entry.get('is_bucket'):
                # Editing a BUCKET entry directly — update the bucket record to match
                # Preserve any prior depletion: if original was 500 and current is 300,
                # that means 200 was depleted. If user sets new value to 600,
                # new original_amount = 600, new entry amount = 600 - 200 = 400
                from recurring_bucket_manager import get_bucket_table_for_entry_table
                bucket_table = get_bucket_table_for_entry_table(table_name)
                
                old_original = float(existing_entry.get('original_amount', existing_entry.get('amount', 0)))
                old_current = float(existing_entry.get('amount', 0))
                depleted = max(old_original - old_current, 0)
                new_original = float(amount)
                new_entry_amount = max(new_original - depleted, 0)
                
                if bucket_table:
                    entry_date_obj = date
                    if isinstance(entry_date_obj, str):
                        from datetime import date as date_type
                        entry_date_obj = date_type.fromisoformat(entry_date_obj)
                    
                    redis_key = f"{bucket_table}:v1:{current_user.id}"
                    redis_data = _redis_client.get(redis_key) if _redis_client else None
                    if redis_data:
                        import json as _json
                        bucket_list = _json.loads(redis_data)
                        for record in bucket_list:
                            if (int(record.get('category_id', 0)) == int(category_id) and
                                str(record.get('bucket_date', '')) == str(entry_date_obj)):
                                record['amount'] = new_entry_amount
                                record['original_amount'] = new_original
                                break
                        _redis_client.setex(redis_key, 604800, _json.dumps(bucket_list, cls=DecimalEncoder))
                        _redis_client.sadd(f"dirty_tables:{current_user.id}", bucket_table)
                        _redis_client.expire(f"dirty_tables:{current_user.id}", 604800)
            
            elif existing_entry and not existing_entry.get('is_bucket'):
                # Editing a regular (non-bucket) entry — restore old amount, deplete new amount
                old_amount = Decimal(str(existing_entry.get('amount', 0)))
                
                entry_date = date
                if isinstance(entry_date, str):
                    from datetime import date as date_type
                    entry_date = date_type.fromisoformat(entry_date)
                
                if recurring_info:
                    from bucket_utils import restore_bucket_for_deleted_entry
                    restore_bucket_for_deleted_entry(
                        table_name,
                        category_id,
                        entry_date,
                        old_amount,
                        current_user.id,
                        recurring_info
                    )
                else:
                    from bucket_utils import restore_bucket_for_deleted_entry_v2
                    restore_bucket_for_deleted_entry_v2(
                        table_name,
                        category_id,
                        old_amount,
                        current_user.id
                    )
            
            # Deplete the new amount from the next bucket (only for non-bucket entries)
            if not existing_entry or not existing_entry.get('is_bucket'):
                process_manual_entry_with_bucket(
                    table_name, category_id, date, 
                    float(amount), current_user.id, recurring_info
                )
        except Exception as e:
            app.logger.error(f"[BUCKET] Error processing bucket depletion: {e}")
            app.logger.exception(e)
            # Continue with normal entry creation even if bucket processing fails
        
        is_editing_bucket = existing_entry and existing_entry.get('is_bucket')
        if is_editing_bucket:
            # Use the depletion-adjusted amount for the entry, and new_original for original_amount
            old_original = float(existing_entry.get('original_amount', existing_entry.get('amount', 0)))
            old_current = float(existing_entry.get('amount', 0))
            depleted = max(old_original - old_current, 0)
            adjusted_amount = max(float(amount) - depleted, 0)
            _update_entry_in_redis(table_name, current_user.id, category_id, date, adjusted_amount, 
                                   match_entry_id=entry_id,
                                   is_bucket=True,
                                   original_amount=float(amount))
        else:
            _update_entry_in_redis(table_name, current_user.id, category_id, date, amount, 
                                   match_entry_id=entry_id)
    
    # If this is an expense category and is_credit_account=1, update payment entry and trigger CA balance update
    if entry_type == 'expense' and cat_data.get('is_credit_account', 0) == 1:
        ca_triggered = True
        # Find the credit account using credit_account_id FK
        account_id = cat_data.get('credit_account_id')
        if account_id:
            account_id = int(account_id)
            # Update or delete payment entry in Redis based on amount
            if float(amount) == 0:
                pass
                _delete_payment_entry_in_redis(current_user.id, account_id, date, date)
            else:
                pass
                _update_payment_entry_in_redis(current_user.id, account_id, date, float(amount))
    else:
        pass

    if entry_type == 'ca' or ca_triggered:
        save_ca_daily_balance()
    
    # Get updated bucket information to return to frontend
    updated_buckets = _get_updated_buckets_from_redis(table_name, current_user.id, category_id, 'day', date)

    return jsonify({"status": "success", "updated_buckets": updated_buckets})

@app.route('/delete-entry', methods=['POST'])
@login_required
def delete_entry():
    data = request.get_json()
    category_id = data.get('category_id')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    entry_type = data.get('type')
    entry_id = data.get('entry_id')  # Optional: specific entry ID for precise targeting

    ca_triggered = False
    payment_category_name = None
    account_id = None

    if entry_type == 'income':
        table_name = 'income_entries'
        category_table = 'income_categories'
    elif entry_type == 'expense':
        table_name = 'expense_entries'
        category_table = 'expense_categories'
    elif entry_type == 'ca':
        table_name = 'c_expense_entries'
        category_table = 'c_expense_categories'
    else:
        return jsonify({'status': 'error', 'message': 'Invalid entry type'}), 400

    # Validate category exists - check Redis first for temp IDs, then MySQL
    cat_data = {}
    if isinstance(category_id, int) and category_id < 0:
        # Temp ID - check Redis
        cats = _get_categories_from_redis(category_table, current_user.id)
        if cats:
            cat_data = next((cat for cat in cats if cat.get('id') == category_id), None)
            if not cat_data:
                app.logger.error(f"[DELETE ENTRY] Temp category {category_id} not found")
                return jsonify({'status': 'error', 'message': 'Invalid category_id for this entry type'}), 400
        else:
            app.logger.error(f"[DELETE ENTRY] No categories in Redis")
            return jsonify({'status': 'error', 'message': 'Invalid category_id for this entry type'}), 400
    else:
        # Real ID - check MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)

            # User isolation for CA: join through credit_accounts
            if entry_type == 'ca':
                cursor.execute(f"""
                    SELECT cec.*
                    FROM c_expense_categories cec
                    JOIN credit_accounts ca ON cec.account_id = ca.id
                    WHERE cec.id = %s AND ca.user_id = %s
                """, (category_id, current_user.id))
                cat_row = cursor.fetchone()
                if not cat_row:
                    cursor.close()
                    return jsonify({'status': 'error', 'message': 'Invalid category_id for this entry type'}), 400
            else:
                cursor.execute(f"SELECT * FROM {category_table} WHERE id = %s AND user_id = %s", (category_id, current_user.id))
                cat_row = cursor.fetchone()
                if not cat_row:
                    cursor.close()
                    return jsonify({'status': 'error', 'message': 'Invalid category_id for this entry type'}), 400
            
            # Make a copy of cat_row data before closing cursor
            cat_data = dict(cat_row) if cat_row else {}
            cursor.close()
    
    # Delete from Redis only - flush worker will persist to MySQL
    _delete_entry_in_redis(table_name, current_user.id, category_id, start_date, end_date,
                           specific_entry_id=entry_id)
    
    # Check if this is a savings category - update savings if so
    is_savings_category = False
    if entry_type in ['income', 'expense'] and cat_data.get('name') == 'Savings':
        is_savings_category = True
    
    # If this is an expense category and is_credit_account=1, delete payment entry and trigger CA balance update
    if entry_type == 'expense' and cat_data.get('is_credit_account', 0) == 1:
        ca_triggered = True
        # Find the credit account using credit_account_id FK
        account_id = cat_data.get('credit_account_id')
        if account_id:
            account_id = int(account_id)
            # Delete payment entries for this account and date range
            _delete_payment_entry_in_redis(current_user.id, account_id, start_date, end_date)

    if entry_type == 'ca' or ca_triggered:
        save_ca_daily_balance()
    
    # Update totals and savings if this is a savings category or regular income/expense
    if is_savings_category or entry_type in ['income', 'expense']:
        save_totals_remainders_d()
    
    # Get updated bucket information to return to frontend
    updated_buckets = _get_updated_buckets_from_redis(table_name, current_user.id, category_id, 'day', end_date)

    return jsonify({'status': 'success', 'updated_buckets': updated_buckets})

@app.route('/check_and_initialize_totals', methods=['POST'])
@login_required
def check_and_initialize_totals():
    try:
        data = request.get_json()
        fridays = data.get('fridays', [])

        if not fridays:
            return jsonify({"status": "error", "message": "No Fridays provided"}), 400

        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)

            # Iterate over each provided Friday
            for friday in fridays:
                friday_date = friday['date']

                # Check if a record for this Friday already exists in totals_remainders
                cursor.execute("""
                    SELECT COUNT(*) as count FROM totals_remainders
                    WHERE user_id = %s AND date = %s
                """, (current_user.id, friday_date))
                record_exists = cursor.fetchone()['count']

                # If no record exists, create it with default values (0 for totals)
                if record_exists == 0:
                    cursor.execute("""
                        INSERT INTO totals_remainders (user_id, date, total_income, total_expenses, remainder, last_week_remainder)
                        VALUES (%s, %s, %s, %s, %s, %s)
                    """, (current_user.id, friday_date, 0.00, 0.00, 0.00, 0.00))

            # Commit the changes to the database
            cursor.close()
            conn.commit()

        return jsonify({"status": "success", "message": "Missing records initialized."})
    except mysql.connector.Error as e:
        return jsonify({"status": "error", "message": str(e)}), 500
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
    
@app.route('/update-processed-status-week-range', methods=['POST'])
@login_required
def update_processed_status_week_range():
    from redis_crud import get_entries, bulk_update_entries
    from datetime import datetime
    
    data = request.get_json()
    category_id = data.get('category_id')
    category_type = data.get('category_type')  # 'income', 'expense', or 'ca'
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    processed = data.get('processed')

    if not category_id or not category_type or not start_date or not end_date or processed is None:
        return jsonify({'status': 'error', 'message': 'Missing required parameters'}), 400

    try:
        # Determine the table name
        if category_type == 'income':
            table_name = 'income_entries'
        elif category_type == 'expense':
            table_name = 'expense_entries'
        elif category_type == 'ca':
            table_name = 'c_expense_entries'
        else:
            return jsonify({'status': 'error', 'message': 'Invalid category type'}), 400

        # Parse dates
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d').date()
        end_date_obj = datetime.strptime(end_date, '%Y-%m-%d').date()
        
        # Get all entries for this category (Redis-first)
        all_entries = get_entries(table_name, {'category_id': int(category_id)}, user_id=current_user.id)
        
        
        # Filter entries within date range
        entries_to_update = []
        for entry in all_entries:
            entry_date = entry.get('date')
            # Handle both date objects and string dates
            if isinstance(entry_date, str):
                entry_date = datetime.strptime(entry_date, '%Y-%m-%d').date()
            
            if start_date_obj <= entry_date <= end_date_obj:
                entries_to_update.append(entry)
        
        
        if not entries_to_update:
            return jsonify({'status': 'success', 'message': 'No entries found in date range'})
        
        # Prepare bulk update - convert processed to int
        processed_int = int(processed)
        updates = [{'id': entry['id'], 'processed': processed_int} for entry in entries_to_update]
        
        # Update using Redis-first approach
        success = bulk_update_entries(table_name, updates, user_id=current_user.id)
        
        if success:
            pass
            
            # Calculate if all entries in this date range for this category are now processed
            all_entries_in_range = get_entries(table_name, {'category_id': int(category_id)}, user_id=current_user.id)
            entries_in_date_range = []
            for entry in all_entries_in_range:
                entry_date = entry.get('date')
                if isinstance(entry_date, str):
                    entry_date = datetime.strptime(entry_date, '%Y-%m-%d').date()
                if start_date_obj <= entry_date <= end_date_obj:
                    entries_in_date_range.append(entry)
            
            # Check if all entries are processed - convert to int for comparison
            all_processed = all(int(entry.get('processed', 0)) == 1 for entry in entries_in_date_range) if entries_in_date_range else False
            
            return jsonify({
                'status': 'success',
                'all_processed': all_processed,
                'entries_updated': len(updates)
            })
        else:
            return jsonify({'status': 'error', 'message': 'Failed to update entries'}), 500

    except Exception as e:
        app.logger.error(f"Error in update_processed_status_week_range: {str(e)}", exc_info=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500
    
