@app.route('/recurring-ca-expense')
@login_required
def recurring_ca_expense():
    # Try Redis first
    recurring_ca_expense_records = _get_recurring_from_redis('recurring_c_expense', current_user.id)
    
    if recurring_ca_expense_records is None:
        # Fallback to MySQL
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)

            # Fetch recurring CA expense records, including no_end_date and name from c_expense_categories
            cursor.execute("""
                SELECT rce.id, rce.user_id, rce.category_id, cec.account_id, cec.name as category_name, rce.amount, 
                       rce.cadence_interval, rce.cadence_unit, rce.weekdays, rce.monthly_days, 
                       rce.start_date, rce.end_date, rce.yearly_day, rce.yearly_month,
                       cec.no_end_date, rce.wage_bill
                FROM recurring_c_expense rce
                JOIN c_expense_categories cec ON rce.category_id = cec.id
                JOIN credit_accounts ca ON cec.account_id = ca.id
                WHERE rce.user_id = %s
            """, (current_user.id,))
            recurring_ca_expense_records = cursor.fetchall()
            cursor.close()
            
            # Cache to Redis
            _set_recurring_to_redis('recurring_c_expense', current_user.id, recurring_ca_expense_records)
    else:
        # Enrich Redis data with account_id and category_name from c_expense_categories
        # This ensures older records have the required fields for template rendering
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("""
                SELECT id, account_id, name, no_end_date
                FROM c_expense_categories
                WHERE account_id IN (SELECT id FROM credit_accounts WHERE user_id = %s)
            """, (current_user.id,))
            categories = {row['id']: row for row in cursor.fetchall()}
            cursor.close()
        
        # Enrich each record
        for record in recurring_ca_expense_records:
            category_id = record.get('category_id')
            if category_id in categories:
                # Add missing fields if not present
                if 'account_id' not in record:
                    record['account_id'] = categories[category_id]['account_id']
                if 'category_name' not in record:
                    record['category_name'] = categories[category_id]['name']
                if 'no_end_date' not in record:
                    record['no_end_date'] = categories[category_id]['no_end_date']
            
            # Ensure account_id is an integer for template comparison
            if 'account_id' in record and not isinstance(record['account_id'], int):
                try:
                    record['account_id'] = int(record['account_id'])
                except (ValueError, TypeError):
                    pass  # Leave as-is if conversion fails
    
    # Fetch credit accounts and user profile data
    with get_db_pool().get_connection() as conn:
        cursor = conn.cursor(pymysql.cursors.DictCursor)
        
        # Fetch all credit accounts for the current user
        cursor.execute("""
            SELECT * FROM credit_accounts
            WHERE user_id = %s
            ORDER BY display_order DESC
        """, (current_user.id,))
        credit_accounts = cursor.fetchall()

        # Fetch ALL c_expense_categories for the searchable category dropdown
        cursor.execute("""
            SELECT cec.id, cec.account_id, cec.name, cec.display_order, cec.is_recurring, cec.hidden,
                   cec.is_interest, cec.is_auto_adjustment, cec.is_bud
            FROM c_expense_categories cec
            WHERE cec.account_id IN (SELECT id FROM credit_accounts WHERE user_id = %s)
            ORDER BY cec.account_id, cec.display_order DESC
        """, (current_user.id,))
        ca_categories_for_dropdown = cursor.fetchall()

        # Fetch user profile data
        cursor.execute("SELECT profile_picture, first_name, last_name, landing_page, currency_type FROM users WHERE id = %s", (current_user.id,))
        user_data = cursor.fetchone()
        cursor.close()

    profile_picture = user_data['profile_picture'] if user_data else None
    first_name = user_data['first_name'] if user_data else ''
    last_name = user_data['last_name'] if user_data else ''
    landing_page = user_data['landing_page'] if user_data and user_data['landing_page'] else 'dashboard_3m'
    currency_type = user_data['currency_type'] if user_data and 'currency_type' in user_data else 'USD'

    current_date = date.today()
    no_end_date = date(current_date.year + 3, 12, 31)

    # Get bucket records for calculating spent amounts
    bucket_records = _get_entries_from_redis('recurring_c_expense_buckets', current_user.id) or []
    
    # Create lookup for bucket records by category_id (use int for consistent comparison)
    today_str = date.today().isoformat()
    bucket_by_category = {}
    for bucket in bucket_records:
        cat_id = int(bucket.get('category_id')) if bucket.get('category_id') is not None else None
        bucket_date = bucket.get('bucket_date')
        if cat_id is None or not bucket_date:
            continue
        bucket_date_str = bucket_date if isinstance(bucket_date, str) else bucket_date.isoformat()
        existing = bucket_by_category.get(cat_id)
        if existing is None:
            bucket_by_category[cat_id] = bucket
        else:
            existing_str = existing.get('bucket_date') if isinstance(existing.get('bucket_date'), str) else existing.get('bucket_date').isoformat()
            if bucket_date_str >= today_str and existing_str >= today_str:
                if bucket_date_str < existing_str:
                    bucket_by_category[cat_id] = bucket
            elif bucket_date_str >= today_str:
                bucket_by_category[cat_id] = bucket
            elif existing_str < today_str and bucket_date_str > existing_str:
                bucket_by_category[cat_id] = bucket

    for record in recurring_ca_expense_records:
        record['cadence_description'] = get_cadence_description(
            record['cadence_interval'],
            record['cadence_unit'],
            record['weekdays'],
            record['monthly_days'],
            record['yearly_day'],
            record['yearly_month']
        )
        if record['end_date'] == no_end_date.strftime('%Y-%m-%d'):
            record['display_end_date'] = 'No end date'
        else:
            record['display_end_date'] = record['end_date']
        
        # Add bucket information
        cat_id = int(record.get('category_id')) if record.get('category_id') is not None else None
        bucket_record = bucket_by_category.get(cat_id)
        
        if bucket_record:
            original_amount = float(bucket_record.get('original_amount', 0))
            current_amount = float(bucket_record.get('amount', 0))
            spent_amount = original_amount - current_amount
            record['bucket_original'] = original_amount
            record['bucket_remaining'] = current_amount
            record['bucket_spent'] = spent_amount
            record['bucket_date'] = bucket_record.get('bucket_date')
        else:
            record['bucket_original'] = None
            record['bucket_remaining'] = None
            record['bucket_spent'] = None
            record['bucket_date'] = None

    return render_template(
        'recurring_ca_e.html',
        recurring_ca_expense_records=recurring_ca_expense_records,
        credit_accounts=credit_accounts,  # <-- Pass this to the template
        ca_categories_for_dropdown=ca_categories_for_dropdown,  # <-- Available categories for new recurring
        profile_picture=profile_picture,
        first_name=first_name,
        last_name=last_name,
        current_date=current_date,
        landing_page=landing_page,
        currency_type=currency_type
    )

@app.route('/add-recurring-ca-expense', methods=['POST'])
@login_required
def add_recurring_ca_expense():
    data = request.get_json()
    if not data:
        return jsonify({'status': 'error', 'message': 'No data received'}), 400

    account_id = data.get('account_id')
    category_id = data.get('category_id')
    amount = data.get('amount')
    cadence_interval = data.get('cadence_interval')
    cadence_unit = data.get('cadence_unit')
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    weekdays = data.get('weekdays')
    monthly_days = data.get('monthly_days')
    yearly_day = data.get('yearly_day')
    yearly_month = data.get('yearly_month')
    no_end_date = data.get('no_end_date', 0)
    wage_bill = data.get('wage_bill', 0)

    # Validate the data - now requires category_id instead of category_name
    if not all([account_id, category_id, amount, cadence_interval, cadence_unit, start_date, end_date]):
        return jsonify({'status': 'error', 'message': 'Missing required fields'}), 400

    try:
        # Verify the category exists and belongs to this account/user
        categories = _get_categories_from_redis('c_expense_categories', current_user.id)
        category_name = None
        if categories is not None:
            for cat in categories:
                if int(cat.get('id')) == int(category_id) and int(cat.get('account_id')) == int(account_id):
                    category_name = cat.get('name')
                    break
        
        if category_name is None:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT cec.name FROM c_expense_categories cec
                    JOIN credit_accounts ca ON cec.account_id = ca.id
                    WHERE cec.id = %s AND cec.account_id = %s AND ca.user_id = %s
                """, (category_id, account_id, current_user.id))
                row = cursor.fetchone()
                cursor.close()
                if row:
                    category_name = row[0]
                else:
                    return jsonify({'status': 'error', 'message': 'Invalid category for this account'}), 400

        # Mark the category as recurring in Redis
        if categories is not None:
            for cat in categories:
                if int(cat.get('id')) == int(category_id):
                    cat['is_recurring'] = 1
                    cat['no_end_date'] = no_end_date
                    break
            redis_key = f"c_expense_categories:v1:{current_user.id}"
            _redis_client.setex(redis_key, 604800, json.dumps(categories, cls=DecimalEncoder))
            _redis_client.sadd(f"dirty_tables:{current_user.id}", 'c_expense_categories')
        else:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    UPDATE c_expense_categories SET is_recurring = 1, no_end_date = %s
                    WHERE id = %s AND account_id = %s
                """, (no_end_date, category_id, account_id))
                conn.commit()
                cursor.close()

        # Create recurring CA expense record in Redis
        recurring_data = {
            'id': None,  # Will be generated by Redis helper
            'user_id': current_user.id,
            'category_id': int(category_id),
            'account_id': int(account_id),
            'category_name': category_name,
            'amount': float(amount),
            'cadence_interval': cadence_interval,
            'cadence_unit': cadence_unit,
            'weekdays': ','.join(weekdays) if weekdays else None,
            'monthly_days': ','.join(map(str, monthly_days)) if monthly_days else None,
            'yearly_day': yearly_day if yearly_day else None,
            'yearly_month': yearly_month if yearly_month else None,
            'start_date': start_date,
            'end_date': end_date,
            'no_end_date': no_end_date,
            'wage_bill': wage_bill
        }
        
        _update_recurring_in_redis('recurring_c_expense', current_user.id, recurring_data)
        
        # Use a temporary ID for generating entries (will be replaced on flush)
        recurring_id = recurring_data['id']

        # Generate CA expense entries based on the cadence
        if recurring_id:
            generate_ca_expense_entries(
                recurring_id, int(category_id), amount, cadence_interval, cadence_unit,
                start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month, current_user.id, account_id
            )

        # Sync updated categories to Ntropy (non-blocking)
        _trigger_ntropy_sync(current_user.id)

        return jsonify({'status': 'success', 'recurring_id': recurring_id, 'message': 'Recurring CA expense added successfully!'})

    except Exception as e:
        return jsonify({'status': 'error', 'message': f'An error occurred while adding the recurring CA expense: {str(e)}'}), 500

def generate_ca_expense_entries(recurring_id, category_id, amount, cadence_interval, cadence_unit, start_date_str, end_date_str, weekdays=None, monthly_days=None, yearly_day=None, yearly_month=None, user_id=None, account_id=None):
    # Get user_id and account_id from the category via credit_accounts if not provided
    if user_id is None or account_id is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            cursor.execute("""
                SELECT ca.user_id, cec.account_id
                FROM c_expense_categories cec
                JOIN credit_accounts ca ON cec.account_id = ca.id
                WHERE cec.id = %s
            """, (category_id,))
            result = cursor.fetchone()
            cursor.close()
            if result:
                if user_id is None:
                    user_id = result['user_id']
                if account_id is None:
                    account_id = result['account_id']
            elif user_id is None:
                return  # Can't proceed without user_id

    start_date = datetime.strptime(start_date_str, '%Y-%m-%d').date()
    current_date = start_date
    end_date = datetime.strptime(end_date_str, '%Y-%m-%d').date()

    while current_date <= end_date:
        delta = None

        if cadence_unit == 'days':
            # Insert bucket entry to Redis
            _update_entry_in_redis('c_expense_entries', user_id, category_id, current_date, float(amount), 
                                 processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
            # Create bucket record using passed account_id
            from recurring_bucket_manager import create_bucket_record
            if account_id:
                create_bucket_record('c_expense_entries', user_id, category_id, current_date, float(amount), account_id=account_id)
            delta = timedelta(days=int(cadence_interval))

        elif cadence_unit == 'weeks':
            for weekday in weekdays:
                weekday_num = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'].index(weekday)
                weekday_date = current_date + timedelta(days=(weekday_num - current_date.weekday()) % 7)
                if start_date <= weekday_date <= end_date:
                    # Insert bucket entry to Redis
                    _update_entry_in_redis('c_expense_entries', user_id, category_id, weekday_date, float(amount), 
                                         processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
                    # Create bucket record using passed account_id
                    from recurring_bucket_manager import create_bucket_record
                    if account_id:
                        create_bucket_record('c_expense_entries', user_id, category_id, weekday_date, float(amount), account_id=account_id)
            delta = timedelta(weeks=int(cadence_interval))

        elif cadence_unit == 'months':
                if monthly_days:
                    monthly_days_cleaned = []
                    for day in monthly_days:
                        if str(day).lower() == 'last day':
                            monthly_days_cleaned.append('Last Day')
                        else:
                            try:
                                monthly_days_cleaned.append(int(day))
                            except Exception:
                                continue
                    year = current_date.year
                    month = current_date.month
                    while True:
                        for day in monthly_days_cleaned:
                            try:
                                if str(day).lower() == 'last day':
                                    day_num = calendar.monthrange(year, month)[1]
                                else:
                                    day_num = int(day)
                                    last_day_of_month = calendar.monthrange(year, month)[1]
                                    if day_num > last_day_of_month:
                                        continue
                                entry_date = date(year=year, month=month, day=day_num)
                            except Exception:
                                continue
                            if entry_date < start_date:
                                continue
                            if entry_date > end_date:
                                continue
                            # Insert bucket entry to Redis
                            _update_entry_in_redis('c_expense_entries', user_id, category_id, entry_date, float(amount), 
                                                 processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
                            # Create bucket record using passed account_id
                            from recurring_bucket_manager import create_bucket_record
                            if account_id:
                                create_bucket_record('c_expense_entries', user_id, category_id, entry_date, float(amount), account_id=account_id)
                        month += int(cadence_interval)
                        while month > 12:
                            month -= 12
                            year += 1
                        if (year > end_date.year) or (year == end_date.year and month > end_date.month):
                            break
                else:
                    year = current_date.year
                    month = current_date.month
                    while True:
                        entry_date = date(year=year, month=month, day=1)
                        if entry_date < start_date:
                            pass
                        elif entry_date > end_date:
                            break
                        else:
                            # Insert bucket entry to Redis
                            _update_entry_in_redis('c_expense_entries', user_id, category_id, entry_date, float(amount), 
                                                 processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
                            # Create bucket record using passed account_id
                            from recurring_bucket_manager import create_bucket_record
                            if account_id:
                                create_bucket_record('c_expense_entries', user_id, category_id, entry_date, float(amount), account_id=account_id)
                        month += int(cadence_interval)
                        while month > 12:
                            month -= 12
                            year += 1
                        if (year > end_date.year) or (year == end_date.year and month > end_date.month):
                            break
                break

        elif cadence_unit == 'years':
            if yearly_day and yearly_month:
                interval = int(cadence_interval)
                year = start_date.year
                while True:
                    try:
                        yearly_entry_date = date(year=year, month=int(yearly_month), day=int(yearly_day))
                    except ValueError:
                        year += interval
                        continue
                    if yearly_entry_date < start_date:
                        year += interval
                        continue
                    if yearly_entry_date > end_date:
                        break
                    # Insert bucket entry to Redis
                    _update_entry_in_redis('c_expense_entries', user_id, category_id, yearly_entry_date, float(amount), 
                                         processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
                    # Create bucket record using passed account_id
                    from recurring_bucket_manager import create_bucket_record
                    if account_id:
                        create_bucket_record('c_expense_entries', user_id, category_id, yearly_entry_date, float(amount), account_id=account_id)
                    year += interval
            else:
                interval = int(cadence_interval)
                year = start_date.year
                while True:
                    yearly_entry_date = date(year=year, month=1, day=1)
                    if yearly_entry_date < start_date:
                        year += interval
                        continue
                    if yearly_entry_date > end_date:
                        break
                    # Insert bucket entry to Redis
                    _update_entry_in_redis('c_expense_entries', user_id, category_id, yearly_entry_date, float(amount), 
                                         processed=0, entry_id=None, is_bucket=True, original_amount=float(amount), recurring_id=recurring_id)
                    # Create bucket record using passed account_id
                    from recurring_bucket_manager import create_bucket_record
                    if account_id:
                        create_bucket_record('c_expense_entries', user_id, category_id, yearly_entry_date, float(amount), account_id=account_id)
                    year += interval

        # Increment current_date
        if delta:
            current_date += delta
        else:
            break
    
    # After generating all entries, update credit account balances
    # Get goofy_week_mode for the user (Redis first, then MySQL)
    goofy_week_mode = None
    if app.config.get('REDIS_OK'):
        try:
            cached = _redis_client.get(f"users:v1:{user_id}")
            if cached:
                user_data = json.loads(cached)
                if 'goofy_week_mode' in user_data:
                    goofy_week_mode = bool(int(user_data['goofy_week_mode']))
        except Exception:
            pass
    if goofy_week_mode is None:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT goofy_week_mode FROM users WHERE id = %s", (user_id,))
            result = cursor.fetchone()
            goofy_week_mode = bool(result[0]) if result else False
            cursor.close()
    
    # Update CA balances (daily, weekly, monthly) - these now update Redis automatically
    update_daily_ca_totals(user_id, start_date)
    update_weekly_ca_totals(user_id, start_date, goofy_week_mode)
    update_monthly_ca_totals(user_id, start_date)

@app.route('/delete-recurring-ca-expense', methods=['POST'])
@login_required
def delete_recurring_ca_expense():
    try:
        data = request.get_json()
        recurring_id = data.get('recurring_id')
        if not recurring_id:
            return jsonify({'status': 'error', 'message': 'Recurring ID not provided.'}), 400

        # Find the recurring record in Redis
        category_id = None
        account_id = None
        cached_recurring = _get_recurring_from_redis('recurring_c_expense', current_user.id)
        if cached_recurring:
            for rec in cached_recurring:
                if int(rec.get('id')) == int(recurring_id):
                    category_id = rec.get('category_id')
                    break
        
        # If not found in Redis, check MySQL to get category_id
        if category_id is None:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT category_id FROM recurring_c_expense WHERE id = %s AND user_id = %s
                """, (recurring_id, current_user.id))
                category = cursor.fetchone()
                cursor.close()
                if not category:
                    return jsonify({'status': 'error', 'message': 'Recurring CA expense not found.'}), 404
                category_id = category[0]
        
        if not category_id:
            return jsonify({'status': 'error', 'message': 'Category ID not found for recurring CA expense.'}), 404
        
        # Get account_id from Redis or MySQL
        cached_categories = _get_categories_from_redis('c_expense_categories', current_user.id)
        if cached_categories:
            for cat in cached_categories:
                if int(cat.get('id')) == int(category_id):
                    account_id = cat.get('account_id')
                    break
        
        if not account_id and int(category_id) > 0:
            # Category exists in MySQL, get account_id from there
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("SELECT account_id FROM c_expense_categories WHERE id = %s", (category_id,))
                account_row = cursor.fetchone()
                cursor.close()
                account_id = account_row[0] if account_row else None
        
        # Convert to non-recurring instead of deleting the category
        # Keep past entries, remove future entries, remove recurring/bucket records
        today = date.today()
        category_id_int = int(category_id)
        
        # 1. Remove future entries (today and onward), keep past entries
        entries = _get_entries_from_redis('c_expense_entries', current_user.id)
        if entries:
            filtered_entries = []
            deleted_entry_ids = []
            for e in entries:
                if int(e.get('category_id', 0)) == category_id_int:
                    entry_date = datetime.strptime(e.get('date'), '%Y-%m-%d').date() if isinstance(e.get('date'), str) else e.get('date')
                    if entry_date >= today:
                        # Future entry - mark for deletion
                        entry_id = e.get('id')
                        if entry_id and int(entry_id) > 0:
                            deleted_entry_ids.append(str(entry_id))
                    else:
                        # Past entry - keep
                        filtered_entries.append(e)
                else:
                    filtered_entries.append(e)
            
            if len(filtered_entries) < len(entries):
                _set_entries_to_redis('c_expense_entries', current_user.id, filtered_entries)
                
                # Track pending entry deletions
                if deleted_entry_ids and app.config.get('REDIS_OK'):
                    pending_key = f"pending_deletes:c_expense_entries:{current_user.id}"
                    _redis_client.sadd(pending_key, *deleted_entry_ids)
                    _redis_client.expire(pending_key, 604800)
                    _redis_client.sadd(f"dirty_tables:{current_user.id}", 'c_expense_entries')
        
        # 2. Delete all buckets for this category from Redis
        _delete_buckets_in_redis('recurring_c_expense_buckets', current_user.id, category_id)
        
        # 3. Delete the recurring record from Redis (marks for deletion)
        _delete_recurring_in_redis('recurring_c_expense', current_user.id, recurring_id)
        
        # 4. Set category to non-recurring (keep the category itself)
        _update_category_in_redis('c_expense_categories', current_user.id, category_id, {
            'is_recurring': 0,
            'no_end_date': 0
        })
        
        # Sync updated categories to Ntropy (non-blocking)
        _trigger_ntropy_sync(current_user.id)
        
        return jsonify({'status': 'success', 'message': 'Recurring category converted to regular category.'})

    except Exception as e:
        app.logger.error(f"Error deleting recurring CA expense: {e}")
        return jsonify({'status': 'error', 'message': 'An error occurred while deleting the recurring CA expense.'}), 500


@app.route('/update-recurring-ca-expense', methods=['POST'])
@login_required
def update_recurring_ca_expense():
    data = request.get_json()
    return update_recurring_ca_expense_inner(data, current_user.id)

def update_recurring_ca_expense_inner(data, user_id):
    try:
        recurring_id = data.get('recurring_id')
        amount = data.get('amount')
        cadence_interval = data.get('cadence_interval')
        cadence_unit = data.get('cadence_unit')
        start_date = data.get('start_date')
        end_date = data.get('end_date')
        weekdays = data.get('weekdays')
        monthly_days = data.get('monthly_days')
        yearly_day = data.get('yearly_day')
        yearly_month = data.get('yearly_month')
        no_end_date = data.get('no_end_date', 0)
        wage_bill = data.get('wage_bill', 0)

        if not all([recurring_id, amount, cadence_interval, cadence_unit, start_date, end_date]):
            return jsonify({'status': 'error', 'message': 'Missing required fields'}), 400

        today = datetime.today().date()
        if datetime.strptime(start_date, '%Y-%m-%d').date() < today:
            return jsonify({'status': 'error', 'message': 'Start date cannot be earlier than today'}), 400
        if datetime.strptime(end_date, '%Y-%m-%d') < datetime.strptime(start_date, '%Y-%m-%d'):
            return jsonify({'status': 'error', 'message': 'End date cannot be earlier than start date'}), 400

        # First, try to find the recurring record in Redis (handles temp negative IDs)
        cached_recurring = _get_recurring_from_redis('recurring_c_expense', user_id)
        category_id = None
        existing_category_name = None
        account_id_value = None
        
        if cached_recurring:
            for rec in cached_recurring:
                if int(rec.get('id')) == int(recurring_id):
                    category_id = rec.get('category_id')
                    existing_category_name = rec.get('category_name')
                    account_id_value = rec.get('account_id')
                    break
        
        # If not in Redis, fall back to MySQL
        if not category_id:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT rce.category_id, cec.name as category_name, cec.account_id 
                    FROM recurring_c_expense rce
                    JOIN c_expense_categories cec ON rce.category_id = cec.id
                    WHERE rce.id = %s AND rce.user_id = %s
                """, (recurring_id, user_id))
                result = cursor.fetchone()
                cursor.close()
                if not result:
                    return jsonify({'status': 'error', 'message': 'Recurring CA expense not found'}), 404
                category_id = result[0]
                existing_category_name = result[1]
                account_id_value = result[2]
        
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor()

            # Step 2: Update the recurring CA expense record in Redis
            recurring_data = {
                'id': recurring_id,
                'user_id': user_id,
                'category_id': category_id,
                'account_id': account_id_value,  # Include the account_id
                'category_name': existing_category_name,  # Include the category name
                'amount': float(amount),
                'cadence_interval': cadence_interval,
                'cadence_unit': cadence_unit,
                'weekdays': ','.join(weekdays) if weekdays else None,
                'monthly_days': ','.join(map(str, monthly_days)) if monthly_days else None,
                'yearly_day': yearly_day if yearly_day else None,
                'yearly_month': yearly_month if yearly_month else None,
                'start_date': start_date,
                'end_date': end_date,
                'no_end_date': no_end_date,
                'wage_bill': wage_bill
            }
            
            _update_recurring_in_redis('recurring_c_expense', user_id, recurring_data)

            # Step 3: Delete old CA expense entries for today and the future from Redis
            _delete_entry_in_redis('c_expense_entries', user_id, category_id, today, date(9999, 12, 31))
            
            # Step 3b: Delete future bucket records for this category
            _delete_future_buckets_in_redis('recurring_c_expense_buckets', user_id, category_id, today)

            conn.commit()
            cursor.close()

        # Step 4: Recreate the CA expense entries with the updated details (only for today and future)
        # Now writes to Redis, so works with both temp (negative) and real (positive) IDs
        if recurring_id:
            generate_ca_expense_entries(
                recurring_id, category_id, amount, cadence_interval, cadence_unit,
                start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month
            )

        # Sync updated categories to Ntropy (non-blocking) - category name may have changed
        _trigger_ntropy_sync(user_id)
        
        return jsonify({'status': 'success', 'message': 'Recurring CA expense updated successfully!'})

    except Exception as e:
        return jsonify({'status': 'error', 'message': f'An error occurred: {str(e)}'}), 500

