def _create_auto_adjustment_for_bank_balance(user_id, bank_balance, account_name_lower=''):
    """
    Create an auto-adjustment entry to match Blankee remainder with bank balance.
    Called when a checking account is connected or enabled.
    Uses YESTERDAY's date so the adjustment doesn't interfere with today's entries.
    
    Returns: (success: bool, message: str)
    """
    try:
        from datetime import date as date_class, timedelta as td
        yesterday = date_class.today() - td(days=1)
        today_str = yesterday.strftime('%Y-%m-%d')
        
        # Get yesterday's remainder from Redis or MySQL
        today_remainder = None
        
        # Try Redis first
        cached_daily = _get_totals_remainders_from_redis('totals_remainders_d', user_id)
        if cached_daily:
            for row in cached_daily:
                row_date = datetime.strptime(row['date'], '%Y-%m-%d').date() if isinstance(row['date'], str) else row['date']
                if row_date == yesterday:
                    today_remainder = float(row.get('remainder', 0))
                    break
        
        # Fallback to MySQL if not in Redis
        if today_remainder is None:
            pass
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT remainder FROM totals_remainders_d
                    WHERE user_id = %s AND date = %s
                    LIMIT 1
                """, (user_id, today_str))
                result = cursor.fetchone()
                cursor.close()
                
                if result:
                    today_remainder = float(result['remainder'])
                else:
                    pass
                    return False, "No remainder data found for yesterday"
        
        bank_balance_float = float(bank_balance)
        
        # Calculate difference
        diff = bank_balance_float - today_remainder
        
        # Skip if difference is negligible (less than 1 cent)
        if abs(diff) < 0.01:
            pass
            return True, f"No adjustment needed - balance already matches (${bank_balance_float:.2f})"
        
        # Determine if we need income or expense adjustment
        entry_type = 'income' if diff > 0 else 'expense'
        table_name = 'income_entries' if diff > 0 else 'expense_entries'
        
        # Find Uncategorized category
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor(pymysql.cursors.DictCursor)
            if entry_type == 'income':
                cursor.execute("""
                    SELECT id, name FROM income_categories 
                    WHERE user_id = %s AND is_auto_adjustment = 1 
                    LIMIT 1
                """, (user_id,))
            else:
                cursor.execute("""
                    SELECT id, name FROM expense_categories 
                    WHERE user_id = %s AND is_auto_adjustment = 1 
                    LIMIT 1
                """, (user_id,))
            
            auto_cat = cursor.fetchone()
            cursor.close()
        
        if not auto_cat:
            app.logger.error(f"[AUTO-ADJUSTMENT] User {user_id}: No Uncategorized category found for {entry_type}")
            return False, f"No Uncategorized category found for {entry_type}"
        
        category_id = auto_cat['id']
        adjustment_amount = abs(diff)
        
        # Add adjustment entry to Redis (will be flushed to MySQL)
        existing_data = _get_entries_from_redis(table_name, user_id)
        
        # If not in Redis, load from MySQL first
        if existing_data is None:
            existing_data = []
            with get_db_pool().get_connection() as conn:
                cursor2 = conn.cursor(pymysql.cursors.DictCursor)
                if entry_type == 'income':
                    cursor2.execute("""
                        SELECT ie.* FROM income_entries ie
                        JOIN income_categories ic ON ie.category_id = ic.id
                        WHERE ic.user_id = %s
                    """, (user_id,))
                else:
                    cursor2.execute("""
                        SELECT ee.* FROM expense_entries ee
                        JOIN expense_categories ec ON ee.category_id = ec.id
                        WHERE ec.user_id = %s
                    """, (user_id,))
                existing_data = list(cursor2.fetchall())
                cursor2.close()
            existing_data = _filter_pending_deletions(table_name, user_id, existing_data)
        
        # Check if auto-adjustment entry already exists for today
        existing_entry = None
        if existing_data:
            for entry in existing_data:
                if str(entry.get('category_id')) == str(category_id) and str(entry.get('date')) == today_str:
                    existing_entry = entry
                    break
        
        if existing_entry:
            # Update existing entry
            new_amount = Decimal(existing_entry.get('amount', 0)) + Decimal(adjustment_amount)
            _update_entry_in_redis(table_name, user_id, category_id, today_str, float(new_amount), processed=1, is_auto_adjustment=True)
        else:
            # Create new entry
            _update_entry_in_redis(table_name, user_id, category_id, today_str, float(adjustment_amount), processed=1, is_auto_adjustment=True)
        
        return True, f"Auto-adjustment created: {entry_type} of ${adjustment_amount:.2f} to match bank balance ${bank_balance_float:.2f}"
        
    except Exception as e:
        app.logger.error(f"[AUTO-ADJUSTMENT] Error for user {user_id}: {e}", exc_info=True)
        return False, f"Error creating auto-adjustment: {str(e)}"


def _update_savings_balance_from_bank(user_id, bank_savings_balance, quiltt_account_id=None):
    """
    Create a savings adjustment entry to reconcile with the bank balance.
    The adjustment stores the DELTA (difference) between bank balance and calculated balance.
    This delta persists through recalculations and is ADDED to the calculated value.
    Uses YESTERDAY's date so the adjustment doesn't interfere with today's entries.
    
    Args:
        user_id: User ID
        bank_savings_balance: Current savings balance from the bank
        quiltt_account_id: Optional Quiltt account ID for reference
        
    Returns: (success: bool, message: str)
    """
    try:
        from datetime import date as date_class, timedelta as td
        yesterday = date_class.today() - td(days=1)
        today_str = yesterday.strftime('%Y-%m-%d')
        
        app.logger.info(f"[SAVINGS-ADJUST] Creating adjustment for user {user_id}: bank balance ${bank_savings_balance}")
        
        # Get current calculated savings for today (before adjustment)
        current_calculated_savings = 0.0
        savings_entries = _get_savings_entries_from_redis(user_id)
        
        if savings_entries:
            for entry in savings_entries:
                entry_date = entry.get('date')
                if isinstance(entry_date, str):
                    if entry_date == today_str:
                        current_calculated_savings = float(entry.get('amount', 0))
                        break
                elif entry_date == yesterday:
                    current_calculated_savings = float(entry.get('amount', 0))
                    break
        
        if current_calculated_savings == 0.0:
            # Fallback to MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT amount FROM savings_entries
                    WHERE user_id = %s AND date = %s
                """, (user_id, today_str))
                result = cursor.fetchone()
                if result:
                    current_calculated_savings = float(result['amount'])
                cursor.close()
        
        # Calculate the delta (what we need to add to match bank balance)
        bank_balance_float = float(bank_savings_balance)
        adjustment_delta = bank_balance_float - current_calculated_savings
        
        app.logger.info(f"[SAVINGS-ADJUST] Calculated savings: ${current_calculated_savings}, Bank: ${bank_balance_float}, Delta: ${adjustment_delta}")
        
        # Get current savings adjustments from Redis
        adjustments = _get_savings_adjustments_from_redis(user_id)
        
        if adjustments is None:
            # Load from MySQL if not in Redis
            adjustments = []
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT id, user_id, date, amount, description, quiltt_account_id
                    FROM savings_adjustments
                    WHERE user_id = %s
                    ORDER BY date
                """, (user_id,))
                for row in cursor.fetchall():
                    adjustments.append({
                        'id': row['id'],
                        'user_id': row['user_id'],
                        'date': row['date'].isoformat() if isinstance(row['date'], date_class) else row['date'],
                        'amount': float(row['amount']) if row['amount'] else 0,
                        'description': row['description'],
                        'quiltt_account_id': row['quiltt_account_id']
                    })
                cursor.close()
        
        # Always create a new "Bank balance sync" adjustment
        # (Don't touch any existing adjustments - those stay as historical records)
        existing_ids = [int(a.get('id', 0)) for a in adjustments if a.get('id')]
        min_id = min(existing_ids) if existing_ids else 0
        temp_id = min_id - 1 if min_id <= 0 else -1
        
        adjustments.append({
            'id': temp_id,
            'user_id': user_id,
            'date': today_str,
            'amount': float(adjustment_delta),
            'description': 'Bank balance sync',
            'quiltt_account_id': quiltt_account_id
        })
        # Sort by date
        adjustments.sort(key=lambda x: x['date'])
        app.logger.info(f"[SAVINGS-ADJUST] Created new bank sync adjustment for {today_str}: ${adjustment_delta}")
        
        # Save to Redis
        _set_savings_adjustments_to_redis(user_id, adjustments)
        
        # Note: We don't call update_daily_savings_for_savings_category here because
        # the calling code (quiltt_auto_adjust_checking) already calls save_totals_remainders_d()
        # which will apply the adjustment. Calling it here would double-apply the delta.
        
        return True, f"Savings adjustment created: delta ${adjustment_delta:.2f} (bank ${bank_balance_float:.2f})"
        
    except Exception as e:
        app.logger.error(f"[SAVINGS-ADJUST] Error for user {user_id}: {e}", exc_info=True)
        return False, f"Error creating savings adjustment: {str(e)}"


def _create_credit_account_auto_adjustment(user_id, quiltt_account_id, bank_balance, account_mask):
    """
    Create an auto-adjustment entry for a credit account to match the bank balance.
    Called when a credit account is connected/enabled via Quiltt.
    
    Args:
        user_id: User ID
        quiltt_account_id: Quiltt account ID (used as primary lookup)
        bank_balance: Current balance from the bank
        account_mask: Account mask (fallback for matching)
        
    Returns: (success: bool, message: str)
    """
    try:
        from datetime import date as date_class, timedelta as td
        yesterday = date_class.today() - td(days=1)
        today_str = yesterday.strftime('%Y-%m-%d')
        
        app.logger.info(f"[CA-AUTO-ADJUST] Creating adjustment for user {user_id}, quiltt_id {quiltt_account_id}, mask {account_mask}: bank balance ${bank_balance}")
        
        # Find the credit account - first by quiltt_account_id, then by mask
        credit_accounts = None
        redis_key = f"credit_accounts:v1:{user_id}"
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(redis_key)
                if cached:
                    credit_accounts = json.loads(cached)
            except Exception as e:
                app.logger.error(f"[CA-AUTO-ADJUST] Redis error: {e}")
        
        if credit_accounts is None:
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("SELECT * FROM credit_accounts WHERE user_id = %s ORDER BY display_order DESC", (user_id,))
                credit_accounts = list(cursor.fetchall())
                cursor.close()
        
        # Find the matching credit account - quiltt_account_id first, then mask
        target_account = None
        for ca in credit_accounts:
            # Primary: match by quiltt_account_id
            if ca.get('quiltt_account_id') == quiltt_account_id:
                target_account = ca
                app.logger.info(f"[CA-AUTO-ADJUST] Found credit account by quiltt_account_id {quiltt_account_id}")
                break
            # Fallback: match by mask
            elif ca.get('mask') == account_mask and not target_account:
                target_account = ca
                app.logger.info(f"[CA-AUTO-ADJUST] Found credit account by mask {account_mask}")
        
        if not target_account:
            app.logger.warning(f"[CA-AUTO-ADJUST] No credit account found for quiltt_id {quiltt_account_id} or mask {account_mask}")
            return False, f"No credit account found for quiltt_id {quiltt_account_id} or mask {account_mask}"
        
        account_id = target_account.get('id')
        starting_balance = float(target_account.get('starting_balance', 0))
        
        # NOTE: We do NOT skip auto-adjustment based on Starting Balance entry existence.
        # The callers handle the "just created" case:
        #   - toggle-sync uses credit_account_was_created flag to skip calling this function
        #   - sync-profile only calls this for existing accounts (not newly created ones)
        # If an existing account has a Starting Balance entry but the bank balance differs,
        # the auto-adjustment should still run to reconcile the difference.
        
        # Get current calculated balance for this credit account
        # The balance = starting_balance + expenses - payments
        # We need to find the current calculated balance and adjust to match bank
        
        c_a_balances = None
        balance_key = f"c_a_balances_d:v1:{user_id}"
        if app.config.get('REDIS_OK'):
            try:
                cached = _redis_client.get(balance_key)
                if cached:
                    c_a_balances = json.loads(cached)
            except Exception as e:
                app.logger.error(f"[CA-AUTO-ADJUST] Redis error getting balances: {e}")
        
        current_calculated_balance = starting_balance  # Default to starting balance
        
        if c_a_balances:
            for bal in c_a_balances:
                if str(bal.get('account_id')) == str(account_id) and str(bal.get('date')) == today_str:
                    current_calculated_balance = float(bal.get('balance', starting_balance))
                    break
        
        if current_calculated_balance == starting_balance:
            # Try MySQL
            with get_db_pool().get_connection() as conn:
                cursor = conn.cursor(pymysql.cursors.DictCursor)
                cursor.execute("""
                    SELECT balance FROM c_a_balances_d
                    WHERE account_id = %s AND date = %s
                """, (account_id, today_str))
                result = cursor.fetchone()
                if result:
                    current_calculated_balance = float(result['balance'])
                cursor.close()
        
        bank_balance_float = float(bank_balance)
        
        # Calculate difference (how much we need to add as expense to match bank balance)
        # Bank shows what we owe, calculated balance shows what we think we owe
        diff = bank_balance_float - current_calculated_balance
        
        app.logger.info(f"[CA-AUTO-ADJUST] Calculated balance: ${current_calculated_balance}, Bank: ${bank_balance_float}, Diff: ${diff}")
        
        # Skip if difference is negligible
        if abs(diff) < 0.01:
            return True, f"No adjustment needed - balance already matches (${bank_balance_float:.2f})"
        
        adjustment_amount = abs(diff)
        
        if diff > 0:
            # Balance needs to go UP (bank balance higher than calculated)
            # Create a c_expense_entries record
            
            # Get categories for this credit account
            c_expense_categories = None
            cat_key = f"c_expense_categories:v1:{user_id}"
            if app.config.get('REDIS_OK'):
                try:
                    cached = _redis_client.get(cat_key)
                    if cached:
                        c_expense_categories = json.loads(cached)
                except Exception as e:
                    app.logger.error(f"[CA-AUTO-ADJUST] Redis error getting categories: {e}")
            
            if c_expense_categories is None:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor(pymysql.cursors.DictCursor)
                    cursor.execute("""
                        SELECT * FROM c_expense_categories WHERE account_id = %s
                    """, (account_id,))
                    c_expense_categories = list(cursor.fetchall())
                    cursor.close()
            
            # Prefer Starting Balance category over Uncategorized for the adjustment.
            # This makes the balance reconciliation more transparent to the user.
            target_cat = None
            
            # First look for Starting Balance category for this account
            for cat in (c_expense_categories or []):
                if (str(cat.get('account_id')) == str(account_id) and 
                    cat.get('name') == 'Starting Balance' and 
                    not cat.get('is_auto_adjustment')):
                    target_cat = cat
                    app.logger.info(f"[CA-AUTO-ADJUST] Using Starting Balance category (id={cat.get('id')}) for adjustment")
                    break
            
            # Fall back to Uncategorized (auto-adjustment) category
            if not target_cat:
                for cat in (c_expense_categories or []):
                    if str(cat.get('account_id')) == str(account_id) and cat.get('is_auto_adjustment') == 1:
                        target_cat = cat
                        app.logger.info(f"[CA-AUTO-ADJUST] No Starting Balance category found, using Uncategorized (id={cat.get('id')})")
                        break
            
            if not target_cat:
                # Create the Uncategorized category if nothing exists
                app.logger.info(f"[CA-AUTO-ADJUST] Creating missing Uncategorized category for account {account_id}")
                new_cat_id = _add_category_to_redis('c_expense_categories', user_id, {
                    'account_id': account_id,
                    'name': 'Uncategorized',
                    'display_order': 0,
                    'group_id': None,
                    'is_recurring': 0,
                    'no_end_date': 0,
                    'hidden': 0,
                    'is_bud': 0,
                    'is_interest': 0,
                    'is_auto_adjustment': 1
                })
                
                if new_cat_id:
                    app.logger.info(f"[CA-AUTO-ADJUST] Created Uncategorized category with ID {new_cat_id}")
                    target_cat = {'id': new_cat_id, 'account_id': account_id, 'is_auto_adjustment': 1}
                else:
                    app.logger.error(f"[CA-AUTO-ADJUST] Failed to create Uncategorized category for account {account_id}")
                    return False, f"Failed to create category for credit account adjustment"
            
            category_id = target_cat.get('id')
            
            # Check if a Starting Balance entry already exists — if so, UPDATE it instead of creating a new entry
            is_starting_balance = (target_cat.get('name') == 'Starting Balance')
            if is_starting_balance:
                c_expense_entries = _get_entries_from_redis('c_expense_entries', user_id)
                if c_expense_entries is None:
                    c_expense_entries = []
                
                existing_sb_entry = None
                for entry in c_expense_entries:
                    if int(entry.get('category_id', 0)) == int(category_id):
                        existing_sb_entry = entry
                        break
                
                if existing_sb_entry:
                    # Update existing Starting Balance entry to match bank balance
                    old_amount = float(existing_sb_entry.get('amount', 0))
                    new_amount = old_amount + adjustment_amount
                    existing_sb_entry['amount'] = new_amount
                    existing_sb_entry['original_amount'] = new_amount
                    
                    # Save back to Redis
                    redis_key_entries = f"c_expense_entries:v1:{user_id}"
                    _redis_client.setex(
                        redis_key_entries,
                        PERSISTENT_CACHE_TTL,
                        json.dumps(c_expense_entries, cls=DecimalEncoder)
                    )
                    dirty_key = f"dirty_tables:{user_id}"
                    _redis_client.sadd(dirty_key, 'c_expense_entries')
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                    
                    app.logger.info(f"[CA-AUTO-ADJUST] Updated Starting Balance entry from ${old_amount} to ${new_amount}")
                    return True, f"Starting Balance updated: ${old_amount:.2f} → ${new_amount:.2f} to match bank balance ${bank_balance_float:.2f}"
            
            # Create new expense entry to increase balance
            _update_entry_in_redis('c_expense_entries', user_id, category_id, today_str, float(adjustment_amount), processed=1, is_auto_adjustment=True)
            app.logger.info(f"[CA-AUTO-ADJUST] Created {'Starting Balance' if is_starting_balance else 'expense'} entry for ${adjustment_amount} to increase balance")
            
            return True, f"Credit account expense adjustment: +${adjustment_amount:.2f} to match bank balance ${bank_balance_float:.2f}"
        
        else:
            # Balance needs to go DOWN (bank balance lower than calculated)
            # Create a c_payment_entries record
            
            # Get existing c_payment_entries
            c_payment_entries = _get_entries_from_redis('c_payment_entries', user_id)
            
            if c_payment_entries is None:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor(pymysql.cursors.DictCursor)
                    cursor.execute("""
                        SELECT * FROM c_payment_entries WHERE account_id = %s
                    """, (account_id,))
                    c_payment_entries = list(cursor.fetchall())
                    cursor.close()
            
            # Create payment entry to decrease balance
            # Use _update_ca_payment_entry_in_redis or similar helper
            # Get existing entries for this account
            if c_payment_entries is None:
                c_payment_entries = []
            
            # Generate temp ID for new entry
            existing_ids = [int(e.get('id', 0)) for e in c_payment_entries if e.get('id')]
            min_id = min(existing_ids) if existing_ids else 0
            temp_id = min_id - 1 if min_id <= 0 else -1
            
            # Add new payment entry
            new_entry = {
                'id': temp_id,
                'account_id': account_id,
                'date': today_str,
                'amount': float(adjustment_amount),
                'recurring_id': None,
                'processed': 1
            }
            c_payment_entries.append(new_entry)
            
            # Save to Redis
            redis_key = f"c_payment_entries:v1:{user_id}"
            if app.config.get('REDIS_OK'):
                _redis_client.setex(
                    redis_key,
                    PERSISTENT_CACHE_TTL,
                    json.dumps(c_payment_entries, cls=DecimalEncoder)
                )
                # Mark as dirty
                dirty_key = f"dirty_tables:{user_id}"
                _redis_client.sadd(dirty_key, 'c_payment_entries')
                _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
            
            app.logger.info(f"[CA-AUTO-ADJUST] Created payment entry for ${adjustment_amount} to decrease balance")
            
            return True, f"Credit account payment adjustment: -${adjustment_amount:.2f} to match bank balance ${bank_balance_float:.2f}"
        
    except Exception as e:
        app.logger.error(f"[CA-AUTO-ADJUST] Error for user {user_id}: {e}", exc_info=True)
        return False, f"Error creating credit account auto-adjustment: {str(e)}"


@app.route('/quiltt/toggle-sync', methods=['POST'])
@login_required
def quiltt_toggle_sync():
    """Toggle transaction sync for a specific account (Redis-first)"""
    data = request.get_json()
    account_id = data.get('account_id')
    sync_enabled = data.get('sync_enabled', True)
    
    if not account_id:
        return jsonify({'status': 'error', 'message': 'Missing account_id'}), 400
    
    try:
        from quiltt_redis import get_quiltt_transactions, delete_quiltt_transactions_for_account, get_quiltt_profile, upsert_quiltt_account
        
        if sync_enabled:
            # Refresh session token when enabling sync to ensure fresh API access
            _refresh_quiltt_session_token(current_user.id, current_user.username)
            
            # First, fetch latest balance from Quiltt before doing anything else
            profile = get_quiltt_profile(current_user.id)
            if profile and profile.get('session_token'):
                try:
                    profile_data = quiltt_client.get_profile(profile['session_token'])
                    if profile_data and profile_data.get('connections'):
                        # Find the account and update its balance in Redis
                        for connection in profile_data['connections']:
                            if connection and connection.get('accounts'):
                                for account in connection['accounts']:
                                    if account and account.get('id') == account_id:
                                        # Found the account - update balance in Redis
                                        balance = account.get('balance') or {}
                                        current_balance = abs(float(balance.get('current', 0) or 0))
                                        available_balance = abs(float(balance.get('available', 0) or 0))
                                        
                                        app.logger.info(f"[TOGGLE-SYNC] Refreshed balance for {account_id}: current=${current_balance}, available=${available_balance}")
                                        
                                        # Update the account in Redis with fresh balance
                                        update_quiltt_account_field(account_id, 'current_balance', current_balance, current_user.id)
                                        update_quiltt_account_field(account_id, 'available_balance', available_balance, current_user.id)
                                        break
                except Exception as e:
                    app.logger.warning(f"[TOGGLE-SYNC] Could not refresh balance from Quiltt: {e}")
                    # Continue anyway - we'll use cached balance
            
            # Enable: Set both sync_transactions and is_active to 1
            success_sync = update_quiltt_account_field(
                account_id, 
                'sync_transactions', 
                1,
                current_user.id
            )
            success_active = update_quiltt_account_field(
                account_id, 
                'is_active', 
                1,
                current_user.id
            )
            
            if success_sync and success_active:
                # Get account details AFTER enabling to check if it's a checking account
                accounts = get_quiltt_accounts(current_user.id)
                target_account = None
                for acc in accounts:
                    if acc.get('account_id') == account_id:
                        target_account = acc
                        break
                
                # If this is a credit account, set is_quiltt=1 on the credit account (or create it)
                credit_account_was_created = False  # Track if we just created the account
                if target_account and target_account.get('account_type', '').upper() == 'CREDIT':
                    account_mask = target_account.get('mask')
                    account_name = target_account.get('account_name', 'Credit Account')
                    current_balance = abs(float(target_account.get('current_balance', 0) or 0))
                    
                    if account_mask:
                        # Find and update the credit account
                        redis_key = f"credit_accounts:v1:{current_user.id}"
                        cached = _redis_client.get(redis_key) if app.config.get('REDIS_OK') else None
                        
                        # Only fall back to MySQL when Redis key doesn't exist (cache miss).
                        # If cached is not None (even if empty list), Redis is authoritative —
                        # an empty list means user deleted all accounts and we must not
                        # re-load stale MySQL data that hasn't been flushed yet.
                        if cached is not None:
                            credit_accounts = json.loads(cached)
                        else:
                            # True cache miss - load from MySQL
                            with get_db_pool().get_connection() as conn:
                                cursor = conn.cursor(pymysql.cursors.DictCursor)
                                cursor.execute("SELECT * FROM credit_accounts WHERE user_id = %s ORDER BY display_order DESC", (current_user.id,))
                                credit_accounts = list(cursor.fetchall())
                                cursor.close()
                                # Cache in Redis if we got data from MySQL
                                if credit_accounts and app.config.get('REDIS_OK'):
                                    _redis_client.setex(
                                        redis_key,
                                        PERSISTENT_CACHE_TTL,
                                        json.dumps(credit_accounts, cls=DecimalEncoder)
                                    )
                        
                        # Determine the display name the user wants for this credit account
                        credit_account_display_name = target_account.get('alias') or account_name
                        
                        # Look for existing credit account - first by quiltt_account_id, then by mask
                        existing_account = None
                        updated = False
                        for i, ca in enumerate(credit_accounts):
                            # First check quiltt_account_id (most reliable)
                            if ca.get('quiltt_account_id') == account_id:
                                existing_account = ca
                                credit_accounts[i]['is_quiltt'] = 1
                                updated = True
                                
                                # Rename the credit account to the user's chosen name if different
                                old_name = ca.get('name', '')
                                if old_name != credit_account_display_name:
                                    credit_accounts[i]['name'] = credit_account_display_name
                                    app.logger.info(f"[TOGGLE-SYNC] Renamed credit account '{old_name}' -> '{credit_account_display_name}'")
                                    
                                    # Also rename the payment category
                                    expense_categories = _get_categories_from_redis('expense_categories', current_user.id)
                                    if expense_categories:
                                        old_payment_name = f"{old_name} payment"
                                        credit_account_db_id = ca.get('id')
                                        for ec in expense_categories:
                                            if ec.get('credit_account_id') == credit_account_db_id and ec.get('name') == old_payment_name:
                                                ec['name'] = f"{credit_account_display_name} payment"
                                                app.logger.info(f"[TOGGLE-SYNC] Renamed payment category '{old_payment_name}' -> '{ec['name']}'")
                                                break
                                        _redis_client.setex(
                                            f"expense_categories:v1:{current_user.id}",
                                            PERSISTENT_CACHE_TTL,
                                            json.dumps(expense_categories, cls=DecimalEncoder)
                                        )
                                        _redis_client.sadd(f"dirty_tables:{current_user.id}", 'expense_categories')
                                
                                app.logger.info(f"Found credit account by quiltt_account_id {account_id} (toggle-sync enable)")
                                break
                            # Fallback to mask matching (and set quiltt_account_id for future)
                            elif ca.get('mask') == account_mask and not ca.get('quiltt_account_id'):
                                existing_account = ca
                                credit_accounts[i]['is_quiltt'] = 1
                                credit_accounts[i]['quiltt_account_id'] = account_id  # Link for future
                                updated = True
                                
                                # Rename the credit account to the user's chosen name if different
                                old_name = ca.get('name', '')
                                if old_name != credit_account_display_name:
                                    credit_accounts[i]['name'] = credit_account_display_name
                                    app.logger.info(f"[TOGGLE-SYNC] Renamed credit account '{old_name}' -> '{credit_account_display_name}' (mask match)")
                                    
                                    # Also rename the payment category
                                    expense_categories = _get_categories_from_redis('expense_categories', current_user.id)
                                    if expense_categories:
                                        old_payment_name = f"{old_name} payment"
                                        credit_account_db_id = ca.get('id')
                                        for ec in expense_categories:
                                            if ec.get('credit_account_id') == credit_account_db_id and ec.get('name') == old_payment_name:
                                                ec['name'] = f"{credit_account_display_name} payment"
                                                app.logger.info(f"[TOGGLE-SYNC] Renamed payment category '{old_payment_name}' -> '{ec['name']}' (mask match)")
                                                break
                                        _redis_client.setex(
                                            f"expense_categories:v1:{current_user.id}",
                                            PERSISTENT_CACHE_TTL,
                                            json.dumps(expense_categories, cls=DecimalEncoder)
                                        )
                                        _redis_client.sadd(f"dirty_tables:{current_user.id}", 'expense_categories')
                                
                                app.logger.info(f"Found credit account by mask {account_mask}, linking quiltt_account_id {account_id}")
                                break
                        
                        if updated:
                            # Save back to Redis
                            _redis_client.setex(
                                redis_key,
                                PERSISTENT_CACHE_TTL,
                                json.dumps(credit_accounts, cls=DecimalEncoder)
                            )
                            
                            # Mark as dirty
                            dirty_key = f"dirty_tables:{current_user.id}"
                            _redis_client.sadd(dirty_key, 'credit_accounts')
                            _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                            
                            app.logger.info(f"Set is_quiltt=1 for credit account (toggle-sync enable)")
                        
                        elif not existing_account:
                            # Credit account doesn't exist - create it (mirror bank connection logic)
                            # credit_account_display_name already set above
                            app.logger.info(f"Creating credit account for Quiltt account: {credit_account_display_name} (mask: {account_mask}, quiltt_id: {account_id}) with balance ${current_balance}")
                            
                            # Determine if it's a card or line of credit based on name/type
                            is_card = 1 if 'card' in account_name.lower() else 0
                            is_line = 1 if 'line' in account_name.lower() else 0
                            
                            # Add credit account to Redis (including quiltt_account_id)
                            account_data = {
                                'name': credit_account_display_name,
                                'mask': account_mask,
                                'quiltt_account_id': account_id,  # Store for direct linking
                                'interest_rate': 0.0,
                                'is_card': is_card,
                                'is_line': is_line,
                                'starting_balance': current_balance,
                                'is_quiltt': 1
                            }
                            
                            temp_account_id = _add_credit_account_to_redis(current_user.id, account_data)
                            
                            # Add default categories for the credit account
                            if temp_account_id:
                                # Add all 3 default categories in a SINGLE Redis write to prevent race conditions
                                default_cat_ids = _add_categories_batch_to_redis('c_expense_categories', current_user.id, [
                                    {
                                        'account_id': temp_account_id,
                                        'name': 'Interest Charge',
                                        'display_order': 2,
                                        'group_id': None,
                                        'is_recurring': 0,
                                        'no_end_date': 0,
                                        'hidden': 0,
                                        'is_bud': 0,
                                        'is_interest': 1,
                                        'is_auto_adjustment': 0
                                    },
                                    {
                                        'account_id': temp_account_id,
                                        'name': 'Uncategorized',
                                        'display_order': 0,
                                        'group_id': None,
                                        'is_recurring': 0,
                                        'no_end_date': 0,
                                        'hidden': 0,
                                        'is_bud': 0,
                                        'is_interest': 0,
                                        'is_auto_adjustment': 1
                                    },
                                    {
                                        'account_id': temp_account_id,
                                        'name': 'Starting Balance',
                                        'display_order': 1,
                                        'group_id': None,
                                        'is_recurring': 0,
                                        'no_end_date': 0,
                                        'hidden': 0,
                                        'is_bud': 0,
                                        'is_interest': 0,
                                        'is_auto_adjustment': 0
                                    }
                                ])
                                # IDs are in order: [Interest Charge, Uncategorized, Starting Balance]
                                starting_balance_cat_id = default_cat_ids[2] if len(default_cat_ids) >= 3 else None
                                
                                # Copy all existing expense categories to this new credit account
                                _copy_expense_categories_to_new_credit_account(current_user.id, temp_account_id)
                                
                                # Create matching expense_categories record for payment
                                payment_category_name = f"{credit_account_display_name} payment"
                                
                                # Payment categories always get display_order 1 (top of list)
                                expense_categories = _get_categories_from_redis('expense_categories', current_user.id)
                                new_display_order = 1
                                
                                # Shift all non-system categories at or above this position up by 1
                                if expense_categories:
                                    shifted = False
                                    for cat in expense_categories:
                                        if cat.get('is_auto_adjustment') == 1:
                                            continue
                                        if cat.get('display_order', 0) >= new_display_order:
                                            cat['display_order'] = cat.get('display_order', 0) + 1
                                            shifted = True
                                    if shifted:
                                        _redis_client.set(
                                            f"expense_categories:v1:{current_user.id}",
                                            json.dumps(expense_categories, cls=DecimalEncoder)
                                        )
                                        _redis_client.expire(f"expense_categories:v1:{current_user.id}", PERSISTENT_CACHE_TTL)
                                        _redis_client.sadd(f"dirty_tables:{current_user.id}", 'expense_categories')
                                
                                # Also shift c_expense_categories display_order to stay in sync
                                c_expense_cats_toggle = _get_categories_from_redis('c_expense_categories', current_user.id)
                                if c_expense_cats_toggle:
                                    shifted = False
                                    for cat in c_expense_cats_toggle:
                                        if cat.get('is_auto_adjustment') == 1 or cat.get('is_interest') == 1:
                                            continue
                                        if cat.get('display_order', 0) >= new_display_order:
                                            cat['display_order'] = cat.get('display_order', 0) + 1
                                            shifted = True
                                    if shifted:
                                        _redis_client.set(
                                            f"c_expense_categories:v1:{current_user.id}",
                                            json.dumps(c_expense_cats_toggle, cls=DecimalEncoder)
                                        )
                                        _redis_client.expire(f"c_expense_categories:v1:{current_user.id}", PERSISTENT_CACHE_TTL)
                                        _redis_client.sadd(f"dirty_tables:{current_user.id}", 'c_expense_categories')
                                
                                _add_category_to_redis('expense_categories', current_user.id, {
                                    'user_id': current_user.id,
                                    'name': payment_category_name,
                                    'display_order': new_display_order,
                                    'group_id': None,
                                    'is_recurring': 0,
                                    'is_auto_adjustment': 0,
                                    'no_end_date': 0,
                                    'hidden': 0,
                                    'is_bud': 0,
                                    'is_credit_account': 1,
                                    'credit_account_id': temp_account_id
                                })
                                
                                app.logger.info(f"Created payment category '{payment_category_name}' for credit account (toggle-sync)")
                                
                                # Create starting balance entry if starting_balance > 0
                                if current_balance and float(current_balance) > 0.0:
                                    from datetime import timedelta as _td
                                    today_str = (date.today() - _td(days=1)).strftime('%Y-%m-%d')
                                    
                                    # Add starting balance entry to Redis
                                    try:
                                        redis_key_entries = f"c_expense_entries:v1:{current_user.id}"
                                        cached_entries = _redis_client.get(redis_key_entries)
                                        entries = json.loads(cached_entries) if cached_entries else []
                                        
                                        # Generate temp ID
                                        existing_ids = [int(e.get('id', 0)) for e in entries]
                                        min_id = min(existing_ids) if existing_ids else 0
                                        entry_id = min_id - 1 if min_id <= 0 else -1
                                        
                                        # Add entry
                                        entries.append({
                                            'id': entry_id,
                                            'category_id': starting_balance_cat_id,
                                            'date': today_str,
                                            'amount': float(current_balance),
                                            'recurring_id': None,
                                            'is_bucket': 0,
                                            'original_amount': float(current_balance),
                                            'processed': 0,
                                            'bud_item_id': None
                                        })
                                        
                                        # Save to Redis
                                        _redis_client.setex(
                                            redis_key_entries,
                                            PERSISTENT_CACHE_TTL,
                                            json.dumps(entries, cls=DecimalEncoder)
                                        )
                                        
                                        # Mark dirty
                                        dirty_key_entries = f"dirty_tables:{current_user.id}"
                                        _redis_client.sadd(dirty_key_entries, 'c_expense_entries')
                                        _redis_client.expire(dirty_key_entries, PERSISTENT_CACHE_TTL)
                                        
                                        app.logger.info(f"Created starting balance entry for credit account {account_name}: ${current_balance} (toggle-sync)")
                                        
                                        # Force immediate flush to MySQL so balance records can be created
                                        try:
                                            from redis_manager import flush_dirty_tables_for_user
                                            flush_dirty_tables_for_user(current_user.id)
                                        except Exception as flush_err:
                                            app.logger.error(f"Error during forced flush for Quiltt credit account (toggle-sync): {flush_err}")
                                        
                                        # Recalculate CA balances from scratch
                                        try:
                                            save_ca_daily_balance()
                                            app.logger.info(f"Recalculated CA daily balances for credit account {account_name} (toggle-sync)")
                                        except Exception as balance_err:
                                            app.logger.error(f"Error recalculating CA balances for Quiltt credit account (toggle-sync): {balance_err}")
                                        
                                    except Exception as entry_err:
                                        app.logger.error(f"Error creating starting balance entry (toggle-sync): {entry_err}")
                                
                                app.logger.info(f"Created credit account {account_name} with ID {temp_account_id} and all default categories (toggle-sync)")
                                credit_account_was_created = True  # Mark that we created it
                
                
                # Resync transactions for this specific account only
                # Skip auto-import - only store transactions for historical record
                # Balance adjustment handles syncing the budget to match bank balance
                try:
                    pass
                    success, count, message = _sync_quiltt_transactions_for_user(
                        current_user.id, 
                        specific_account_id=account_id,
                        skip_auto_import=True
                    )
                    
                    # Check if this is a checking account and create auto-adjustment
                    auto_adjustment_msg = ""
                    if target_account:
                        account_name = target_account.get('account_name', '').lower()
                        account_type = target_account.get('account_type', '').lower()
                        current_balance = target_account.get('current_balance', 0)
                        account_mask = target_account.get('mask')
                        
                        
                        # Check if it's a depository account (checking/savings) with a balance
                        if account_type == 'depository' and current_balance:
                            # Differentiate between checking and savings accounts
                            if 'savings' in account_name:
                                # Savings account - create savings adjustment
                                app.logger.info(f"[AUTO-ADJUST] Creating savings adjustment for account '{account_name}' with balance {current_balance}")
                                auto_success, auto_msg = _update_savings_balance_from_bank(
                                    current_user.id, 
                                    current_balance,
                                    account_id
                                )
                                if auto_success:
                                    auto_adjustment_msg = f" | {auto_msg}"
                                    app.logger.info(f"[AUTO-ADJUST-SAVINGS] Success: {auto_msg}")
                                else:
                                    app.logger.warning(f"[AUTO-ADJUST-SAVINGS] Failed: {auto_msg}")
                            else:
                                # Checking account - create income/expense auto-adjustment
                                app.logger.info(f"[AUTO-ADJUST] Creating auto-adjustment for checking account '{account_name}' with balance {current_balance}")
                                auto_success, auto_msg = _create_auto_adjustment_for_bank_balance(
                                    current_user.id, 
                                    current_balance,
                                    account_name
                                )
                                if auto_success:
                                    auto_adjustment_msg = f" | {auto_msg}"
                                    app.logger.info(f"[AUTO-ADJUST] Success: {auto_msg}")
                                else:
                                    app.logger.warning(f"[AUTO-ADJUST] Failed: {auto_msg}")
                        elif account_type == 'credit' and current_balance is not None and account_mask:
                            # Credit account - create credit account auto-adjustment
                            # Skip if we just created the account (already has starting balance entry)
                            if credit_account_was_created:
                                app.logger.info(f"[AUTO-ADJUST-CREDIT] Skipping auto-adjustment - account was just created with starting balance")
                            else:
                                app.logger.info(f"[AUTO-ADJUST] Creating credit account adjustment for '{account_name}' with balance {current_balance}")
                                auto_success, auto_msg = _create_credit_account_auto_adjustment(
                                    current_user.id,
                                    account_id,
                                    current_balance,
                                    account_mask
                                )
                                if auto_success:
                                    auto_adjustment_msg = f" | {auto_msg}"
                                    app.logger.info(f"[AUTO-ADJUST-CREDIT] Success: {auto_msg}")
                                else:
                                    app.logger.warning(f"[AUTO-ADJUST-CREDIT] Failed: {auto_msg}")
                        else:
                            pass
                    
                    if success:
                        return jsonify({
                            'status': 'success', 
                            'message': f'Account enabled and {count} transactions synced{auto_adjustment_msg}'
                        })
                    else:
                        return jsonify({
                            'status': 'warning', 
                            'message': f'Account enabled but sync had issues: {message}{auto_adjustment_msg}'
                        })
                except Exception as tx_error:
                    app.logger.error(f"Error re-syncing transactions: {tx_error}")
                    return jsonify({
                        'status': 'warning',
                        'message': 'Account enabled but transaction sync failed'
                    })
            else:
                return jsonify({'status': 'error', 'message': 'Failed to enable account'}), 500
        else:
            # Disable: Set both sync_transactions and is_active to 0
            success_sync = update_quiltt_account_field(
                account_id, 
                'sync_transactions', 
                0,
                current_user.id
            )
            success_active = update_quiltt_account_field(
                account_id, 
                'is_active', 
                0,
                current_user.id
            )
            
            if success_sync and success_active:
                # Get the Quiltt account to find its mask and type
                quiltt_accounts = get_quiltt_accounts(current_user.id)
                quiltt_account = None
                for qa in quiltt_accounts:
                    if qa.get('account_id') == account_id:
                        quiltt_account = qa
                        break
                
                # If this is a credit account, set is_quiltt=0 and clear quiltt_account_id
                if quiltt_account and quiltt_account.get('account_type', '').upper() == 'CREDIT':
                    # Find and update the credit account by quiltt_account_id first
                    redis_key = f"credit_accounts:v1:{current_user.id}"
                    cached = _redis_client.get(redis_key) if app.config.get('REDIS_OK') else None
                    credit_accounts = json.loads(cached) if cached else []
                    
                    account_mask = quiltt_account.get('mask')
                    # Extract last 4 digits for comparison (Quiltt may store full mask like XXXX-XXXX-XXXX-7691)
                    quiltt_last4 = account_mask[-4:] if account_mask and len(account_mask) >= 4 else account_mask
                    
                    updated = False
                    for i, ca in enumerate(credit_accounts):
                        # Match by quiltt_account_id first
                        if ca.get('quiltt_account_id') == account_id:
                            credit_accounts[i]['is_quiltt'] = 0
                            credit_accounts[i]['quiltt_account_id'] = None  # Clear the link
                            updated = True
                            app.logger.info(f"Set is_quiltt=0 and cleared quiltt_account_id for credit account (toggle-sync off, quiltt_id={account_id})")
                            break
                        # Fallback: match by last 4 digits of mask
                        ca_mask = ca.get('mask')
                        ca_last4 = ca_mask[-4:] if ca_mask and len(ca_mask) >= 4 else ca_mask
                        if quiltt_last4 and ca_last4 and ca_last4 == quiltt_last4:
                            credit_accounts[i]['is_quiltt'] = 0
                            updated = True
                            app.logger.info(f"Set is_quiltt=0 for credit account by mask last4 {ca_last4} (toggle-sync off)")
                            break
                    
                    if updated:
                        # Save back to Redis
                        _redis_client.setex(
                            redis_key,
                            PERSISTENT_CACHE_TTL,
                            json.dumps(credit_accounts, cls=DecimalEncoder)
                        )
                        
                        # Mark as dirty
                        dirty_key = f"dirty_tables:{current_user.id}"
                        _redis_client.sadd(dirty_key, 'credit_accounts')
                        _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
                
                # Delete all transactions for this account from Redis and MySQL
                try:
                    pass
                    delete_quiltt_transactions_for_account(account_id, current_user.id)
                except Exception as del_error:
                    app.logger.error(f"Error deleting transactions: {del_error}")
                
                return jsonify({'status': 'success', 'message': 'Account disabled and transactions removed'})
            else:
                return jsonify({'status': 'error', 'message': 'Failed to disable account'}), 500
        
    except Exception as e:
        app.logger.error(f"Error toggling sync: {e}")
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/quiltt/update-account', methods=['POST'])
@login_required
def quiltt_update_account():
    """Update account settings (is_active, sync_transactions) during setup"""
    data = request.get_json()
    account_id = data.get('account_id')
    is_active = data.get('is_active')
    sync_transactions = data.get('sync_transactions')
    
    if not account_id:
        return jsonify({'status': 'error', 'message': 'Missing account_id'}), 400
    
    try:
        app.logger.info(f"[UPDATE-ACCOUNT] account_id={account_id}, is_active={is_active}, sync_transactions={sync_transactions}, user_id={current_user.id}")
        
        # Update both fields together to avoid race conditions
        from quiltt_redis import update_quiltt_account_fields
        success = update_quiltt_account_fields(
            account_id,
            {
                'is_active': is_active,
                'sync_transactions': sync_transactions
            },
            current_user.id
        )
        
        if not success:
            app.logger.error(f"[UPDATE-ACCOUNT] Failed to update account {account_id} - account not found in Redis or MySQL")
            return jsonify({'status': 'error', 'message': 'Failed to update account'}), 500
        
        # If account is being toggled off (is_active=0 or sync_transactions=0), update credit account is_quiltt to 0
        if is_active == 0 or sync_transactions == 0:
            # Get the Quiltt account to find its mask
            quiltt_accounts = get_quiltt_accounts(current_user.id)
            quiltt_account = None
            for qa in quiltt_accounts:
                if qa.get('account_id') == account_id:
                    quiltt_account = qa
                    break
            
            if quiltt_account and quiltt_account.get('account_type', '').upper() == 'CREDIT':
                # Find and update the credit account by quiltt_account_id first
                redis_key = f"credit_accounts:v1:{current_user.id}"
                cached = _redis_client.get(redis_key) if app.config.get('REDIS_OK') else None
                credit_accounts = json.loads(cached) if cached else []
                
                account_mask = quiltt_account.get('mask')
                # Extract last 4 digits for comparison
                quiltt_last4 = account_mask[-4:] if account_mask and len(account_mask) >= 4 else account_mask
                
                updated = False
                for i, ca in enumerate(credit_accounts):
                    # Match by quiltt_account_id first
                    if ca.get('quiltt_account_id') == account_id:
                        credit_accounts[i]['is_quiltt'] = 0
                        credit_accounts[i]['quiltt_account_id'] = None  # Clear the link
                        updated = True
                        app.logger.info(f"Set is_quiltt=0 and cleared quiltt_account_id (update-account, quiltt_id={account_id})")
                        break
                    # Fallback: match by last 4 digits of mask
                    ca_mask = ca.get('mask')
                    ca_last4 = ca_mask[-4:] if ca_mask and len(ca_mask) >= 4 else ca_mask
                    if quiltt_last4 and ca_last4 and ca_last4 == quiltt_last4:
                        credit_accounts[i]['is_quiltt'] = 0
                        updated = True
                        app.logger.info(f"Set is_quiltt=0 for credit account by mask last4 {ca_last4} (update-account)")
                        break
                
                if updated:
                    # Save back to Redis
                    _redis_client.setex(
                        redis_key,
                        PERSISTENT_CACHE_TTL,
                        json.dumps(credit_accounts, cls=DecimalEncoder)
                    )
                    
                    # Mark as dirty
                    dirty_key = f"dirty_tables:{current_user.id}"
                    _redis_client.sadd(dirty_key, 'credit_accounts')
                    _redis_client.expire(dirty_key, PERSISTENT_CACHE_TTL)
        
        return jsonify({'status': 'success'})
        
    except Exception as e:
        app.logger.error(f"Error updating account {account_id}: {e}", exc_info=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/quiltt/sync-transactions-setup', methods=['POST'])
@login_required
def quiltt_sync_transactions_setup():
    """Sync transactions for specific accounts during setup"""
    data = request.get_json()
    account_ids = data.get('account_ids', [])
    
    if not account_ids:
        return jsonify({'status': 'success', 'message': 'No accounts to sync', 'transactions_synced': 0})
    
    try:
        total_synced = 0
        
        for account_id in account_ids:
            success, count, message = _sync_quiltt_transactions_for_user(
                current_user.id,
                specific_account_id=account_id,
                skip_auto_import=True  # During setup, only store transactions without creating entries
            )
            if success:
                total_synced += count
        
        return jsonify({
            'status': 'success',
            'transactions_synced': total_synced,
            'message': f'Synced {total_synced} transactions'
        })
        
    except Exception as e:
        app.logger.error(f"Error syncing transactions during setup: {e}")
        return jsonify({'status': 'error', 'message': str(e)}), 500


