@app.route('/quiltt/create-recommended-categories', methods=['POST'])
@login_required
def quiltt_create_recommended_categories():
    """
    Create income and expense categories from the recommended categories during profile setup.
    
    This is called after the user completes the threshold page.
    Categories can be recurring or non-recurring.
    For recurring categories, we create the category + recurring record + generate entries.
    For non-recurring categories, we just create the category.
    
    Expected JSON input:
    {
        "income": [
            {"name": "Wages", "is_recurring": true, "amount": 1500, "cadence_interval": 2, 
             "cadence_unit": "weeks", "weekdays": "Friday", "start_date": "2026-01-05", 
             "end_date": null, "no_end_date": true},
            {"name": "Variable", "is_recurring": false}
        ],
        "expense": [
            {"name": "Housing", "is_recurring": true, "amount": 1200, "cadence_interval": 1,
             "cadence_unit": "months", "monthly_days": "1", "start_date": "2026-01-05",
             "end_date": null, "no_end_date": true},
            ...
        ]
    }
    """
    try:
        data = request.get_json()
        if not data:
            return jsonify({'status': 'error', 'message': 'No data received'}), 400
        
        income_categories = data.get('income', [])
        expense_categories = data.get('expense', [])
        
        app.logger.info(f"Creating recommended categories for user_id={current_user.id}: "
                       f"{len(income_categories)} income, {len(expense_categories)} expense")
        
        created_income = []
        created_expense = []
        errors = []
        
        # Calculate 5 years from now for no_end_date categories
        five_years_from_now = (datetime.now() + timedelta(days=365*5)).strftime('%Y-%m-%d')
        today = datetime.now().strftime('%Y-%m-%d')
        
        # Process income categories
        for idx, cat in enumerate(income_categories):
            try:
                result = _create_single_category(
                    user_id=current_user.id,
                    category_type='income',
                    category_data=cat,
                    display_order=idx + 1,
                    today=today,
                    five_years_from_now=five_years_from_now
                )
                created_income.append(result)
            except Exception as e:
                app.logger.error(f"Error creating income category '{cat.get('name')}': {e}")
                errors.append(f"Income '{cat.get('name')}': {str(e)}")
        
        # Process expense categories
        for idx, cat in enumerate(expense_categories):
            try:
                result = _create_single_category(
                    user_id=current_user.id,
                    category_type='expense',
                    category_data=cat,
                    display_order=idx + 1,
                    today=today,
                    five_years_from_now=five_years_from_now
                )
                created_expense.append(result)
            except Exception as e:
                app.logger.error(f"Error creating expense category '{cat.get('name')}': {e}")
                errors.append(f"Expense '{cat.get('name')}': {str(e)}")
        
        # Sync custom categories to Ntropy for transaction enrichment
        _trigger_ntropy_sync(current_user.id)
        
        return jsonify({
            'status': 'success',
            'created': {
                'income': created_income,
                'expense': created_expense
            },
            'errors': errors if errors else None,
            'message': f"Created {len(created_income)} income and {len(created_expense)} expense categories"
        })
        
    except Exception as e:
        app.logger.error(f"Error creating recommended categories: {e}", exc_info=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500


def _create_single_category(user_id, category_type, category_data, display_order, today, five_years_from_now):
    """
    Helper function to create a single category (income or expense).
    For recurring categories, also creates the recurring record and generates entries.
    
    Returns dict with created IDs.
    """
    name = category_data.get('name', '').strip()
    is_recurring = category_data.get('is_recurring', False)
    
    if not name:
        raise ValueError("Category name is required")
    
    # Determine table names based on type
    if category_type == 'income':
        category_table = 'income_categories'
        recurring_table = 'recurring_income'
        entries_table = 'income_entries'
        generate_entries_func = generate_income_entries
    else:
        category_table = 'expense_categories'
        recurring_table = 'recurring_expense'
        entries_table = 'expense_entries'
        generate_entries_func = generate_expense_entries
    
    # Build category data
    new_category = {
        'user_id': user_id,
        'name': name,
        'display_order': display_order,
        'group_id': None,
        'is_recurring': 1 if is_recurring else 0,
        'is_auto_adjustment': 0,
        'no_end_date': 1 if is_recurring and category_data.get('no_end_date', True) else 0,
        'hidden': 0
    }
    
    # Add expense-specific fields
    if category_type == 'expense':
        new_category['is_bud'] = 0
        new_category['is_credit_account'] = 0
    
    # Create category in Redis
    category_id = _add_category_to_redis(category_table, user_id, new_category)
    
    if category_id is None:
        raise ValueError(f"Failed to create category in Redis")
    
    result = {
        'name': name,
        'category_id': category_id,
        'is_recurring': is_recurring
    }
    
    # If recurring, create the recurring record and generate entries
    if is_recurring:
        amount = float(category_data.get('amount', 0))
        cadence_interval = int(category_data.get('cadence_interval', 1))
        cadence_unit = category_data.get('cadence_unit', 'months')
        
        # Parse weekdays (can be string like "Friday" or "Monday,Wednesday")
        weekdays_raw = category_data.get('weekdays')
        if weekdays_raw:
            if isinstance(weekdays_raw, list):
                weekdays = weekdays_raw
            else:
                weekdays = [w.strip().lower() for w in str(weekdays_raw).split(',')]
        else:
            weekdays = None
        
        # Parse monthly_days (can be string like "1" or "1,15")
        monthly_days_raw = category_data.get('monthly_days')
        if monthly_days_raw:
            if isinstance(monthly_days_raw, list):
                monthly_days = monthly_days_raw
            else:
                monthly_days = [d.strip() for d in str(monthly_days_raw).split(',')]
        else:
            monthly_days = None
        
        # Handle yearly fields
        yearly_day = category_data.get('yearly_day')
        yearly_month = category_data.get('yearly_month')
        
        # Determine start and end dates
        start_date = category_data.get('start_date') or today
        no_end_date = category_data.get('no_end_date', True)
        
        if no_end_date:
            end_date = five_years_from_now
        elif category_data.get('occurrences_count'):
            # Calculate end date based on occurrences
            end_date = _calculate_end_date_from_occurrences(
                start_date, cadence_interval, cadence_unit, 
                int(category_data['occurrences_count']), weekdays, monthly_days
            )
        else:
            end_date = category_data.get('end_date') or five_years_from_now
        
        # Create recurring record in Redis
        recurring_data = {
            'id': None,
            'user_id': user_id,
            'category_id': category_id,
            'category_name': name,
            'amount': amount,
            'cadence_interval': cadence_interval,
            'cadence_unit': cadence_unit,
            'weekdays': ','.join(weekdays) if weekdays else None,
            'monthly_days': ','.join(map(str, monthly_days)) if monthly_days else None,
            'yearly_day': yearly_day,
            'yearly_month': yearly_month,
            'start_date': start_date,
            'end_date': end_date,
            'no_end_date': 1 if no_end_date else 0,
            'wage_bill': int(category_data.get('wage_bill', 1))
        }
        
        _update_recurring_in_redis(recurring_table, user_id, recurring_data)
        recurring_id = recurring_data['id']
        
        result['recurring_id'] = recurring_id
        
        # Generate entries
        if recurring_id:
            generate_entries_func(
                recurring_id, category_id, amount, cadence_interval, cadence_unit,
                start_date, end_date, weekdays, monthly_days, yearly_day, yearly_month, user_id
            )
    
    return result


def _calculate_end_date_from_occurrences(start_date_str, cadence_interval, cadence_unit, occurrences, weekdays=None, monthly_days=None):
    """
    Calculate the end date based on number of occurrences.
    """
    from datetime import datetime, timedelta
    import calendar
    
    start_date = datetime.strptime(start_date_str, '%Y-%m-%d').date()
    
    if cadence_unit == 'days':
        # Each occurrence is cadence_interval days apart
        end_date = start_date + timedelta(days=cadence_interval * (occurrences - 1))
    
    elif cadence_unit == 'weeks':
        # Each occurrence is cadence_interval weeks apart
        end_date = start_date + timedelta(weeks=cadence_interval * (occurrences - 1))
    
    elif cadence_unit == 'months':
        # Add cadence_interval months for each occurrence
        months_to_add = cadence_interval * (occurrences - 1)
        year = start_date.year + (start_date.month + months_to_add - 1) // 12
        month = (start_date.month + months_to_add - 1) % 12 + 1
        day = min(start_date.day, calendar.monthrange(year, month)[1])
        end_date = date(year, month, day)
    
    elif cadence_unit == 'years':
        end_date = date(start_date.year + cadence_interval * (occurrences - 1), start_date.month, start_date.day)
    
    else:
        end_date = start_date + timedelta(days=365 * 5)  # Default to 5 years
    
    return end_date.strftime('%Y-%m-%d')


@app.route('/quiltt/auto-adjust-checking', methods=['POST'])
@login_required
def quiltt_auto_adjust_checking():
    """
    Create auto-adjustment entries for all active checking accounts.
    Called after initial setup or when user enables checking accounts.
    """
    try:
        # Get all active accounts for this user
        accounts = get_quiltt_accounts(current_user.id)
        
        app.logger.info(f"[AUTO-ADJUST-CHECKING] User {current_user.id}: Found {len(accounts) if accounts else 0} accounts")
        
        if not accounts:
            app.logger.info(f"[AUTO-ADJUST-CHECKING] User {current_user.id}: No accounts found, returning early")
            return jsonify({'status': 'success', 'message': 'No accounts found'})
        
        adjustments_made = []
        savings_updated = False
        
        for account in accounts:
            # Only process active depository accounts (checking/savings)
            is_active = account.get('is_active', 0)
            sync_transactions = account.get('sync_transactions', 0)
            account_type = account.get('account_type', '').lower()
            account_name = account.get('account_name', '').lower()
            current_balance = account.get('current_balance', 0)
            
            app.logger.info(f"[AUTO-ADJUST-CHECKING] Account: {account.get('account_name')} - type={account_type}, is_active={is_active}, sync_transactions={sync_transactions}, balance={current_balance}")
            
            if is_active and sync_transactions and account_type == 'depository' and current_balance:
                # Check if it's a CHECKING account - create auto-adjustment
                if 'checking' in account_name:
                    app.logger.info(f"[AUTO-ADJUST-CHECKING] Processing CHECKING account '{account.get('account_name')}' with balance {current_balance}")
                    
                    success, message = _create_auto_adjustment_for_bank_balance(
                        current_user.id,
                        current_balance,
                        account_name
                    )
                    
                    if success:
                        adjustments_made.append({
                            'account_name': account.get('account_name'),
                            'balance': float(current_balance),
                            'message': message
                        })
                        app.logger.info(f"[AUTO-ADJUST-CHECKING] Success for {account.get('account_name')}: {message}")
                    else:
                        app.logger.warning(f"[AUTO-ADJUST-CHECKING] Failed for {account.get('account_name')}: {message}")
                
                # Check if it's a SAVINGS account - update savings balance
                elif 'savings' in account_name:
                    app.logger.info(f"[AUTO-ADJUST-CHECKING] Processing SAVINGS account '{account.get('account_name')}' with balance {current_balance}")
                    
                    success, message = _update_savings_balance_from_bank(
                        current_user.id,
                        float(current_balance)
                    )
                    
                    if success:
                        savings_updated = True
                        app.logger.info(f"[AUTO-ADJUST-CHECKING] Savings updated for {account.get('account_name')}: {message}")
                    else:
                        app.logger.warning(f"[AUTO-ADJUST-CHECKING] Failed to update savings for {account.get('account_name')}: {message}")
        
        # Recalculate totals and remainders if any changes were made
        if adjustments_made or savings_updated:
            app.logger.info(f"[AUTO-ADJUST-CHECKING] Recalculating totals for user {current_user.id}")
            try:
                save_totals_remainders_d()
                app.logger.info(f"[AUTO-ADJUST-CHECKING] Totals recalculated successfully")
            except Exception as calc_err:
                app.logger.error(f"[AUTO-ADJUST-CHECKING] Error recalculating totals: {calc_err}")
        
        result_message = []
        if adjustments_made:
            result_message.append(f'Created {len(adjustments_made)} auto-adjustment(s)')
        if savings_updated:
            result_message.append('Updated savings balance')
        
        if result_message:
            return jsonify({
                'status': 'success',
                'adjustments': adjustments_made,
                'savings_updated': savings_updated,
                'message': ' | '.join(result_message)
            })
        else:
            return jsonify({
                'status': 'success',
                'message': 'No accounts needed adjustment'
            })
    
    except Exception as e:
        app.logger.error(f"[AUTO-ADJUST-CHECKING] Error: {e}", exc_info=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/quiltt/toggle-auto-import', methods=['POST'])
@login_required
def quiltt_toggle_auto_import():
    """Toggle automatic transaction import"""
    data = request.get_json()
    enabled = data.get('enabled', True)
    
    try:
        with get_db_pool().get_connection() as conn:
            cursor = conn.cursor()
            cursor.execute("""
                UPDATE users 
                SET quiltt_auto_import = %s
                WHERE id = %s
            """, (1 if enabled else 0, current_user.id))
            conn.commit()
            cursor.close()
        
        return jsonify({'status': 'success'})
        
    except Exception as e:
        app.logger.error(f"Error toggling auto-import: {e}")
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/quiltt/simulate-webhook', methods=['POST'])
@login_required
def quiltt_simulate_webhook():
    """
    Simulate a connection.synced.successful webhook event for the current user.
    Runs the FULL webhook processing pipeline synchronously (not in a background thread)
    so results are returned immediately.
    
    Optional JSON body:
        start_date: YYYY-MM-DD (defaults to last_synced_at fallback)
        end_date: YYYY-MM-DD (defaults to today)
        connection_id: specific connection to simulate for (optional)
    """
    from quiltt_redis import get_quiltt_connections, upsert_quiltt_connection, insert_quiltt_webhook_event, mark_webhook_event_processed
    import uuid

    data = request.get_json(silent=True) or {}
    start_date = data.get('start_date')
    end_date = data.get('end_date')
    target_connection_id = data.get('connection_id')
    user_id = current_user.id

    # Get user's connections
    connections = get_quiltt_connections(user_id)
    if not connections:
        return jsonify({'status': 'error', 'message': 'No Quiltt connections found'}), 400

    # Filter to target connection if specified
    if target_connection_id:
        connections = [c for c in connections if c.get('connection_id') == target_connection_id]
        if not connections:
            return jsonify({'status': 'error', 'message': f'Connection {target_connection_id} not found'}), 400

    results = []
    for conn_info in connections:
        connection_id = conn_info.get('connection_id')
        institution = conn_info.get('institution_name', 'Unknown')
        fake_event_id = f"sim_{uuid.uuid4().hex[:12]}"

        app.logger.info(f"[SIMULATE-WEBHOOK] Simulating connection.synced.successful for user {user_id}, connection {connection_id} ({institution})")

        # 1. Log the simulated event
        try:
            insert_quiltt_webhook_event(
                event_id=fake_event_id,
                event_type='connection.synced.successful',
                profile_id=f'simulated_{user_id}',
                connection_id=connection_id,
                payload={'simulated': True, 'user_id': user_id, 'connection_id': connection_id},
                user_id=user_id
            )
        except Exception as e:
            app.logger.warning(f"[SIMULATE-WEBHOOK] Failed to log event: {e}")

        # 2. Update connection status to SYNCED
        try:
            upsert_quiltt_connection({
                'connection_id': connection_id,
                'status': 'SYNCED',
                'last_synced_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            }, user_id=user_id)
        except Exception as e:
            app.logger.warning(f"[SIMULATE-WEBHOOK] Failed to update connection status: {e}")

        # 3. Sync transactions (the main work)
        success, count, message = _sync_quiltt_transactions_for_user(
            user_id,
            start_date=start_date,
            end_date=end_date
        )

        # 4. Mark event processed
        try:
            error_msg = message if not success else None
            mark_webhook_event_processed(fake_event_id, error_message=error_msg)
        except Exception as e:
            app.logger.warning(f"[SIMULATE-WEBHOOK] Failed to mark event processed: {e}")

        results.append({
            'connection_id': connection_id,
            'institution': institution,
            'success': success,
            'transactions_synced': count,
            'message': message,
            'event_id': fake_event_id
        })

    total_synced = sum(r['transactions_synced'] for r in results)
    all_success = all(r['success'] for r in results)

    return jsonify({
        'status': 'success' if all_success else 'partial',
        'total_transactions_synced': total_synced,
        'connections_processed': len(results),
        'results': results
    })


@app.route('/quiltt/webhook', methods=['POST'])
def quiltt_webhook():
    """
    Receive and process webhook events from Quiltt.
    - Verifies HMAC-SHA256 signature
    - Logs events to quiltt_webhook_events table
    - Returns 200 immediately, processes async via background thread
    """
    import hmac
    import hashlib
    from quiltt_redis import insert_quiltt_webhook_event, mark_webhook_event_processed

    # --- Signature Verification ---
    webhook_secret = os.getenv('QUILTT_WEBHOOK_SECRET', '')
    signature = request.headers.get('Quiltt-Signature', '')
    timestamp = request.headers.get('Quiltt-Timestamp', '')
    raw_body = request.get_data(as_text=True)

    if webhook_secret:
        if not signature or not timestamp:
            app.logger.warning("[WEBHOOK] Missing signature or timestamp headers")
            return jsonify({'error': 'Missing signature'}), 401

        # Verify timestamp is within 5 minutes
        try:
            from datetime import timezone
            # Quiltt sends timestamp as Unix epoch (integer seconds)
            event_time = datetime.fromtimestamp(int(timestamp), tz=timezone.utc)
            now = datetime.now(timezone.utc)
            if abs((now - event_time).total_seconds()) > 300:
                app.logger.warning(f"[WEBHOOK] Timestamp too old: {timestamp}")
                return jsonify({'error': 'Timestamp expired'}), 401
        except (ValueError, TypeError):
            app.logger.warning(f"[WEBHOOK] Invalid timestamp format: {timestamp}")
            return jsonify({'error': 'Invalid timestamp'}), 401

        # Verify HMAC signature: HMAC-SHA256(secret, "1" + timestamp + body)
        message = f"1{timestamp}{raw_body}"
        expected = base64.b64encode(
            hmac.new(webhook_secret.encode(), message.encode(), hashlib.sha256).digest()
        ).decode()
        if not hmac.compare_digest(signature, expected):
            app.logger.warning("[WEBHOOK] Invalid signature")
            return jsonify({'error': 'Invalid signature'}), 401
    else:
        app.logger.warning("[WEBHOOK] No QUILTT_WEBHOOK_SECRET configured — skipping verification")

    # --- Parse Payload ---
    try:
        payload = json.loads(raw_body)
    except (json.JSONDecodeError, TypeError):
        app.logger.error("[WEBHOOK] Invalid JSON payload")
        return jsonify({'error': 'Invalid JSON'}), 400

    events = payload.get('events', [])
    if not events:
        app.logger.info("[WEBHOOK] Received payload with no events")
        return jsonify({'status': 'ok', 'message': 'No events'}), 200

    app.logger.info(f"[WEBHOOK] Received {len(events)} event(s): {[e.get('type') for e in events]}")

    # --- Log Events & Deduplicate ---
    new_events = []
    for event in events:
        event_id = event.get('id', '')
        event_type = event.get('type', '')
        profile = event.get('profile', {})
        profile_id = profile.get('id', '')
        record = event.get('record', {})
        connection_id = record.get('id', '')

        # Resolve user_id from profile metadata (fast path) or DB (fallback)
        user_id = None
        metadata = profile.get('metadata') or {}
        if metadata.get('user_id'):
            user_id = int(metadata['user_id'])
        else:
            # Fallback: look up profile_id in quiltt_profiles
            try:
                with get_db_pool().get_connection() as conn:
                    cursor = conn.cursor(pymysql.cursors.DictCursor)
                    cursor.execute("SELECT user_id FROM quiltt_profiles WHERE profile_id = %s", (profile_id,))
                    row = cursor.fetchone()
                    if row:
                        user_id = row['user_id']
                    cursor.close()
            except Exception as e:
                app.logger.error(f"[WEBHOOK] Error looking up user for profile {profile_id}: {e}")

        # Insert event (INSERT IGNORE handles deduplication)
        inserted = insert_quiltt_webhook_event(
            event_id=event_id,
            event_type=event_type,
            profile_id=profile_id,
            connection_id=connection_id if connection_id else None,
            payload=event,
            user_id=user_id
        )

        if inserted:
            new_events.append({
                'event_id': event_id,
                'event_type': event_type,
                'profile_id': profile_id,
                'connection_id': connection_id,
                'user_id': user_id,
                'event': event
            })
            app.logger.info(f"[WEBHOOK] Logged event {event_id} ({event_type}) for user {user_id}")
        else:
            app.logger.info(f"[WEBHOOK] Duplicate event {event_id} — skipped")

    # --- Async Processing ---
    if new_events:
        def process_webhook_events(events_to_process):
            """Background thread to process webhook events based on event type."""
            with app.app_context():
                for evt in events_to_process:
                    try:
                        event_type = evt['event_type']
                        user_id = evt.get('user_id')
                        event_id = evt['event_id']
                        connection_id = evt.get('connection_id')
                        event_data = evt.get('event', {})
                        metadata = event_data.get('metadata', {})

                        if not user_id:
                            mark_webhook_event_processed(event_id, error_message="Could not resolve user_id")
                            continue

                        app.logger.info(f"[WEBHOOK] Processing {event_type} for user {user_id}")

                        # --- Events that don't need processing ---
                        # initial/historical: handled by frontend UI flow during bank connection
                        # profile.ready: Ntropy data is already fetched inline during sync
                        if event_type in ('connection.synced.successful.initial',
                                          'connection.synced.successful.historical',
                                          'profile.ready'):
                            app.logger.info(f"[WEBHOOK] Skipping {event_type} for user {user_id} — no action needed")
                            mark_webhook_event_processed(event_id)
                            continue

                        # --- Connection Synced Successfully (ongoing periodic re-syncs) ---
                        if event_type == 'connection.synced.successful':

                            # Use date range from webhook metadata if available
                            start_date = metadata.get('startDate')
                            end_date = metadata.get('endDate')

                            # Update connection status to SYNCED
                            if connection_id:
                                try:
                                    from quiltt_redis import upsert_quiltt_connection
                                    upsert_quiltt_connection({
                                        'connection_id': connection_id,
                                        'status': 'SYNCED',
                                        'last_synced_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                                    }, user_id=user_id)
                                except Exception as e:
                                    app.logger.warning(f"[WEBHOOK] Failed to update connection status: {e}")

                            # Sync transactions for this user
                            success, count, error = _sync_quiltt_transactions_for_user(
                                user_id,
                                start_date=start_date,
                                end_date=end_date
                            )

                            if success:
                                app.logger.info(f"[WEBHOOK] Synced {count} transactions for user {user_id}")
                                mark_webhook_event_processed(event_id)
                            else:
                                app.logger.error(f"[WEBHOOK] Sync failed for user {user_id}: {error}")
                                mark_webhook_event_processed(event_id, error_message=error)

                        # --- Connection Errors (user needs to reconnect) ---
                        elif event_type == 'connection.synced.errored.repairable':
                            # Skip if connection was recently deleted (e.g., user went back during setup)
                            conn_was_deleted = False
                            if connection_id:
                                try:
                                    delete_key = f"quiltt_connections_to_delete:{user_id}"
                                    if _redis_client.sismember(delete_key, connection_id):
                                        conn_was_deleted = True
                                except Exception:
                                    pass

                            if conn_was_deleted:
                                app.logger.info(f"[WEBHOOK] Skipping {event_type} for user {user_id} — connection {connection_id} was recently deleted")
                                mark_webhook_event_processed(event_id)
                            else:
                                # Update connection status
                                if connection_id:
                                    try:
                                        from quiltt_redis import upsert_quiltt_connection
                                        upsert_quiltt_connection({
                                            'connection_id': connection_id,
                                            'status': 'ERROR_REPAIRABLE'
                                        }, user_id=user_id)
                                    except Exception as e:
                                        app.logger.warning(f"[WEBHOOK] Failed to update connection status: {e}")

                                # Get institution name for notification
                                institution_name = 'your bank'
                                try:
                                    with get_db_pool().get_connection() as conn:
                                        cursor = conn.cursor(pymysql.cursors.DictCursor)
                                        cursor.execute(
                                            "SELECT institution_name FROM quiltt_connections WHERE connection_id = %s AND user_id = %s",
                                            (connection_id, user_id)
                                        )
                                        row = cursor.fetchone()
                                        if row and row.get('institution_name'):
                                            institution_name = row['institution_name']
                                        cursor.close()
                                except Exception:
                                    pass

                                # Create notification with reconnect link
                                notification_message = (
                                    f'Your {institution_name} connection needs to be reconnected. '
                                    f'<a href="/bank_accounts?reconnect={connection_id}" class="notification-link">'
                                    f'Click here to reconnect</a>.'
                                )
                                add_notification(user_id, notification_message)
                                app.logger.info(f"[WEBHOOK] Created reconnect notification for user {user_id} ({institution_name})")
                                mark_webhook_event_processed(event_id)

                        # --- Connection Disconnected ---
                        elif event_type == 'connection.disconnected':
                            # Skip if connection was recently deleted (e.g., user went back during setup)
                            conn_was_deleted = False
                            if connection_id:
                                try:
                                    delete_key = f"quiltt_connections_to_delete:{user_id}"
                                    if _redis_client.sismember(delete_key, connection_id):
                                        conn_was_deleted = True
                                except Exception:
                                    pass

                            if conn_was_deleted:
                                app.logger.info(f"[WEBHOOK] Skipping {event_type} for user {user_id} — connection {connection_id} was recently deleted")
                                mark_webhook_event_processed(event_id)
                            else:
                                # Update connection status
                                if connection_id:
                                    try:
                                        from quiltt_redis import upsert_quiltt_connection
                                        upsert_quiltt_connection({
                                            'connection_id': connection_id,
                                            'status': 'DISCONNECTED'
                                        }, user_id=user_id)
                                    except Exception as e:
                                        app.logger.warning(f"[WEBHOOK] Failed to update connection status: {e}")

                                institution_name = 'your bank'
                                try:
                                    with get_db_pool().get_connection() as conn:
                                        cursor = conn.cursor(pymysql.cursors.DictCursor)
                                        cursor.execute(
                                            "SELECT institution_name FROM quiltt_connections WHERE connection_id = %s AND user_id = %s",
                                            (connection_id, user_id)
                                        )
                                        row = cursor.fetchone()
                                        if row and row.get('institution_name'):
                                            institution_name = row['institution_name']
                                        cursor.close()
                                except Exception:
                                    pass

                                notification_message = (
                                    f'Your {institution_name} connection has been disconnected. '
                                    f'<a href="/bank_accounts?reconnect={connection_id}" class="notification-link">'
                                    f'Click here to reconnect</a>.'
                                )
                                add_notification(user_id, notification_message)
                                app.logger.info(f"[WEBHOOK] Created disconnect notification for user {user_id} ({institution_name})")
                                mark_webhook_event_processed(event_id)

                        # --- Other error events (log only) ---
                        elif event_type in ('connection.synced.errored.institution',
                                            'connection.synced.errored.provider',
                                            'connection.synced.errored.service'):
                            app.logger.warning(f"[WEBHOOK] Connection error ({event_type}) for user {user_id}, connection {connection_id}")
                            mark_webhook_event_processed(event_id)

                        # --- Unknown event type ---
                        else:
                            app.logger.info(f"[WEBHOOK] Unhandled event type: {event_type}")
                            mark_webhook_event_processed(event_id)

                    except Exception as e:
                        app.logger.error(f"[WEBHOOK] Error processing event {evt.get('event_id')}: {e}", exc_info=True)
                        mark_webhook_event_processed(evt.get('event_id', ''), error_message=str(e))

        thread = threading.Thread(target=process_webhook_events, args=(new_events,), daemon=True)
        thread.start()

    return jsonify({'status': 'ok', 'received': len(events), 'new': len(new_events)}), 200



